window.SEARCH_INDEX = [{"cmd": "cat /etc/os-release", "tip": "Distro, version — the source of truth systemd itself reads, more reliable than /etc/*-release variants.", "section": "System Information", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-system-information"}, {"cmd": "hostnamectl", "tip": "Hostname, kernel, arch, virt type — one command, everything.", "section": "System Information", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-system-information"}, {"cmd": "uname -a", "tip": "Kernel version, arch — confirms exactly what you're running before assuming a feature/syscall is available.", "section": "System Information", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-system-information"}, {"cmd": "timedatectl", "tip": "Timezone, NTP sync status — check this first on cert/log timing bugs.", "section": "System Information", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-system-information"}, {"cmd": "uptime -p", "tip": "Human-readable uptime — quick sanity check on whether a recent restart could explain a symptom.", "section": "System Information", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-system-information"}, {"cmd": "lscpu", "tip": "CPU model, cores, sockets, cache — better than /proc/cpuinfo.", "section": "System Information", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-system-information"}, {"cmd": "lsblk -f", "tip": "Block devices + filesystem + mount, in a tree — see the whole disk layout in one readable view.", "section": "System Information", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-system-information"}, {"cmd": "dmidecode -t system", "tip": "Hardware/BIOS info — needs root, useful when a bug turns out to be hardware/firmware specific.", "section": "System Information", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-system-information"}, {"cmd": "journalctl --list-boots", "tip": "Every boot this machine has had, with timestamps — confirms exactly when a restart happened.", "section": "System Information", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-system-information"}, {"cmd": "lspci", "tip": "PCI devices — GPUs, network cards, controllers.", "section": "System Information", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-system-information"}, {"cmd": "lsusb", "tip": "USB devices connected — confirms a device is actually recognized at the hardware level.", "section": "System Information", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-system-information"}, {"cmd": "nproc", "tip": "Number of usable CPU cores — respects cgroup limits in containers, the number that actually matters there, not the host's physical count.", "section": "System Information", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-system-information"}, {"cmd": "arch", "tip": "Machine hardware name — confirms the CPU architecture before assuming a binary will even run.", "section": "System Information", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-system-information"}, {"cmd": "hostnamectl set-hostname myserver", "tip": "Change the hostname permanently — persists across reboots, unlike a plain hostname command.", "section": "System Information", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-system-information"}, {"cmd": "timedatectl set-timezone Europe/Bucharest", "tip": "Change system timezone — affects how every timestamp on the system is displayed.", "section": "System Information", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-system-information"}, {"cmd": "timedatectl set-ntp true", "tip": "Enable NTP sync if it's currently off — clock drift causes confusing cert/auth failures that look unrelated.", "section": "System Information", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-system-information"}, {"cmd": "dmesg -T | tail -50", "tip": "Last 50 kernel ring buffer messages, human timestamps — recent hardware/driver events without scrolling the whole buffer.", "section": "System Information", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-system-information"}, {"cmd": "cat /proc/version", "tip": "Kernel build info — compiler, build date, builder.", "section": "System Information", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-system-information"}, {"cmd": "who -b", "tip": "Last system boot time, short form — a one-line answer instead of parsing uptime's longer output.", "section": "System Information", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-system-information"}, {"cmd": "nproc --all", "tip": "Total cores including ones a cgroup limit may be hiding from `nproc` alone — the gap between the two is itself diagnostic in containers.", "section": "System Information", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-system-information"}, {"cmd": "cat /sys/class/dmi/id/product_name", "tip": "Hardware model without needing root — dmidecode usually does need it, this is the unprivileged alternative.", "section": "System Information", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-system-information"}, {"cmd": "systemd-detect-virt", "tip": "Confirms bare metal vs VM vs container — and which hypervisor.", "section": "System Information", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-system-information"}, {"cmd": "ps -eo pid,ppid,%cpu,%mem,cmd --sort=-%mem | head", "tip": "Top memory consumers, readable — sorted so the worst offender is right at the top.", "section": "Processes", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-processes"}, {"cmd": "pstree -p", "tip": "Process tree with PIDs — shows parent/child relationships a flat ps list hides.", "section": "Processes", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-processes"}, {"cmd": "ps -ef --forest", "tip": "Same idea as pstree, no extra package needed — built into plain ps.", "section": "Processes", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-processes"}, {"cmd": "top -o %CPU", "tip": "Sort live view by CPU — jumps straight to the worst offender instead of scanning a default-ordered list.", "section": "Processes", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-processes"}, {"cmd": "nice -n 10 ionice -c3 ./heavy_script.sh", "tip": "Lower CPU priority (nice) + idle I/O class (ionice) — run heavy batch jobs without starving the box.", "section": "Processes", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-processes"}, {"cmd": "renice -n 5 -p 1234", "tip": "Change priority of an already-running process — nice only works at launch, this adjusts one already running.", "section": "Processes", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-processes"}, {"cmd": "ionice -c2 -n0 -p 1234", "tip": "Bump I/O priority of a running PID back up — undo an ionice that's now slowing something down too much.", "section": "Processes", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-processes"}, {"cmd": "taskset -c 0,1 ./script.sh", "tip": "Pin a process to specific CPU cores — stops the scheduler from bouncing it between cores, useful for consistent benchmarking.", "section": "Processes", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-processes"}, {"cmd": "chrt -r 10 ./script.sh", "tip": "Run with real-time scheduling (careful — can starve everything else)", "section": "Processes", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-processes"}, {"cmd": "kill -0 1234", "tip": "Exit code 0 = process exists, no signal actually sent — great for scripts.", "section": "Processes", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-processes"}, {"cmd": "strace -p 1234 -f", "tip": "Attach to a running process and see every syscall — the fastest way to find exactly what it's stuck on.", "section": "Processes", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-processes"}, {"cmd": "lsof -p 1234", "tip": "Every file/socket a process has open — confirms what it's actually touching, not just what you assume.", "section": "Processes", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-processes"}, {"cmd": "cat /proc/1234/status", "tip": "Memory, threads, state — no tools needed.", "section": "Processes", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-processes"}, {"cmd": "cat /proc/1234/limits", "tip": "Ulimits actually applied to that process — the real enforced limits, not just what's configured system-wide.", "section": "Processes", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-processes"}, {"cmd": "nohup ./script.sh &gt; out.log 2&gt;&amp;1 &amp;", "tip": "Survives terminal close — the process keeps running after you disconnect or close the SSH session.", "section": "Processes", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-processes"}, {"cmd": "disown -h %1", "tip": "Detach a job from the shell without nohup — useful for a job already running that you forgot to nohup.", "section": "Processes", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-processes"}, {"cmd": "setsid ./script.sh &amp;", "tip": "Fully detach from controlling terminal — stronger than nohup, no terminal signals can reach it at all.", "section": "Processes", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-processes"}, {"cmd": "pgrep -f myprocess", "tip": "Find PIDs by name/command pattern — no ps+grep pipeline needed for the common case.", "section": "Processes", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-processes"}, {"cmd": "pkill -f myprocess", "tip": "Kill by name pattern — skips the step of finding the PID first.", "section": "Processes", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-processes"}, {"cmd": "jobs -l", "tip": "Background jobs in the current shell, with PIDs — confirms what's actually running before fg/kill-ing the wrong one.", "section": "Processes", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-processes"}, {"cmd": "fg %1", "tip": "Bring background job 1 to the foreground — reattaches so you can interact with it directly.", "section": "Processes", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-processes"}, {"cmd": "ulimit -a", "tip": "Every resource limit for the current shell — open files, processes, memory, confirms what's actually enforced.", "section": "Processes", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-processes"}, {"cmd": "ps -o pid,ppid,pgid,sid,comm -p 1234", "tip": "Full ancestry: parent, process group, session — useful for untangling orphaned processes.", "section": "Processes", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-processes"}, {"cmd": "cat /proc/1234/cgroup", "tip": "Which cgroup(s) a process belongs to — the real capacity limits in a container.", "section": "Processes", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-processes"}, {"cmd": "readlink /proc/1234/exe", "tip": "The actual binary a PID launched from — even if the file was since replaced.", "section": "Processes", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-processes"}, {"cmd": "ls -la /proc/1234/fd", "tip": "Every open file descriptor for a process — symlinked to its target, shows exactly what files/sockets it's using.", "section": "Processes", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-processes"}, {"cmd": "free -h", "tip": "Memory overview — quick totals for used/free/swap, human-readable.", "section": "CPU and Memory", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-cpu-and-memory"}, {"cmd": "vmstat 1 5", "tip": "5 samples, 1s apart — watch 'r' (run queue) and 'wa' (I/O wait)", "section": "CPU and Memory", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-cpu-and-memory"}, {"cmd": "mpstat -P ALL 1", "tip": "Per-core CPU usage — reveals imbalance a single averaged number from top would hide.", "section": "CPU and Memory", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-cpu-and-memory"}, {"cmd": "sar -u 1 5", "tip": "Historical CPU stats — needs sysstat installed, shows usage over time instead of just right now.", "section": "CPU and Memory", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-cpu-and-memory"}, {"cmd": "numactl --hardware", "tip": "NUMA topology — matters on multi-socket DB/JVM hosts.", "section": "CPU and Memory", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-cpu-and-memory"}, {"cmd": "pmap -x 1234 | tail -1", "tip": "Total memory footprint of one process, broken down — shared vs private, more accurate than a single RSS number.", "section": "CPU and Memory", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-cpu-and-memory"}, {"cmd": "smem -tk", "tip": "Accounts for shared memory properly — free and ps both double-count it across processes, this doesn't.", "section": "CPU and Memory", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-cpu-and-memory"}, {"cmd": "watch -n1 'free -h'", "tip": "Live-refreshing memory view without extra tools — a poor man's dashboard using only watch + free.", "section": "CPU and Memory", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-cpu-and-memory"}, {"cmd": "top -H -p 1234", "tip": "Per-thread CPU view for one process — find which thread inside a process is hot.", "section": "CPU and Memory", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-cpu-and-memory"}, {"cmd": "free -m --si", "tip": "Memory in MB, SI (1000-based) units — matches how storage vendors usually report size, unlike the default binary units.", "section": "CPU and Memory", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-cpu-and-memory"}, {"cmd": "cat /proc/loadavg", "tip": "Raw load average + running/total process count, scriptable — parseable without stripping uptime's prose formatting.", "section": "CPU and Memory", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-cpu-and-memory"}, {"cmd": "uptime", "tip": "Quick load average without the human-readable wrapper — same numbers, less text to parse.", "section": "CPU and Memory", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-cpu-and-memory"}, {"cmd": "sar -r 1 5", "tip": "Historical memory usage samples — needs sysstat, same sar tool used with -u for CPU history.", "section": "CPU and Memory", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-cpu-and-memory"}, {"cmd": "vmstat -s", "tip": "Cumulative memory/swap stats since boot — a one-shot summary instead of vmstat's repeating samples.", "section": "CPU and Memory", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-cpu-and-memory"}, {"cmd": "numastat -p 1234", "tip": "NUMA memory allocation for one process — cross-node access is a hidden latency source on multi-socket hosts.", "section": "CPU and Memory", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-cpu-and-memory"}, {"cmd": "df -hT", "tip": "Usage + filesystem type — confirms both how full a disk is and what kind of filesystem it is.", "section": "Disk and Storage", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-disk-and-storage"}, {"cmd": "du -sh --max-depth=1 /var | sort -rh", "tip": "Find what's eating a directory, sorted biggest-first — narrows a full disk down to the actual culprit fast.", "section": "Disk and Storage", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-disk-and-storage"}, {"cmd": "findmnt", "tip": "Mount tree, easier to read than plain mount — a cleaner hierarchical view of what's mounted where.", "section": "Disk and Storage", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-disk-and-storage"}, {"cmd": "lsof +D /var/log", "tip": "Who has files open under a directory — essential before umount fails.", "section": "Disk and Storage", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-disk-and-storage"}, {"cmd": "fuser -vm /mnt/data", "tip": "What's using a mount point — confirms what's actually holding it open before an unmount fails.", "section": "Disk and Storage", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-disk-and-storage"}, {"cmd": "iostat -xz 1", "tip": "Per-device I/O — the %util column is the one that actually tells you if a disk is the bottleneck.", "section": "Disk and Storage", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-disk-and-storage"}, {"cmd": "ncdu /var", "tip": "Interactive du — much faster to navigate than plain du.", "section": "Disk and Storage", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-disk-and-storage"}, {"cmd": ": &gt; /var/log/huge.log", "tip": "Truncate a log file in place without deleting it (keeps the inode/fd alive — safe for a process still writing to it)", "section": "Disk and Storage", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-disk-and-storage"}, {"cmd": "mount | column -t", "tip": "Currently mounted filesystems, readable columns — confirms what's mounted where without parsing raw output.", "section": "Disk and Storage", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-disk-and-storage"}, {"cmd": "umount /mnt/data", "tip": "Unmount cleanly — fails loudly if something still has an open file on it, rather than silently corrupting data.", "section": "Disk and Storage", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-disk-and-storage"}, {"cmd": "mount -o remount,rw /", "tip": "Remount root read-write — recovers from a filesystem that mounted read-only after an unclean shutdown.", "section": "Disk and Storage", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-disk-and-storage"}, {"cmd": "fdisk -l", "tip": "List partition tables on every disk — confirms the actual partition layout before making any changes.", "section": "Disk and Storage", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-disk-and-storage"}, {"cmd": "blkid", "tip": "UUID and filesystem type for every block device — the identifiers /etc/fstab actually relies on.", "section": "Disk and Storage", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-disk-and-storage"}, {"cmd": "du -h --max-depth=1 . | sort -rh", "tip": "Same idea as the disk-usage command above, relative to the current directory instead of root.", "section": "Disk and Storage", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-disk-and-storage"}, {"cmd": "tune2fs -l /dev/sda1", "tip": "Ext4 filesystem parameters — last check date, mount count, features enabled.", "section": "Disk and Storage", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-disk-and-storage"}, {"cmd": "fsck -n /dev/sda1", "tip": "Check filesystem without fixing anything (-n = answer no to all repairs) — safe on a mounted disk only for inspection.", "section": "Disk and Storage", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-disk-and-storage"}, {"cmd": "parted -l", "tip": "Partition tables with GPT support — fdisk historically struggled with GPT disks, parted doesn't.", "section": "Disk and Storage", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-disk-and-storage"}, {"cmd": "find / -xdev -type f -size +100M 2&gt;/dev/null", "tip": "Big files, current filesystem only — -xdev skips crawling mounted NFS shares that would slow this way down.", "section": "Files and Directories", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-files-and-directories"}, {"cmd": "find . -mtime -1", "tip": "Modified in the last 24h — narrows a huge directory down to what actually changed recently.", "section": "Files and Directories", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-files-and-directories"}, {"cmd": "find . -type f -newer reference_file", "tip": "Anything newer than a given file — compare against a timestamp marker instead of a fixed time window.", "section": "Files and Directories", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-files-and-directories"}, {"cmd": "find . -name '*.log' -mtime +30 -delete", "tip": "Cleanup — destructive, see Production Safety before running this against anything that matters.", "section": "Files and Directories", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-files-and-directories"}, {"cmd": "rsync -avz --dry-run src/ dst/", "tip": "Always dry-run a sync before committing to it — confirms what would actually change before it does.", "section": "Files and Directories", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-files-and-directories"}, {"cmd": "xargs -P4 -I{} cmd {}", "tip": "Parallelize find/xargs pipelines — 4 at a time, much faster on a large file set.", "section": "Files and Directories", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-files-and-directories"}, {"cmd": "diff &lt;(sort file1) &lt;(sort file2)", "tip": "Process substitution — compare without temp files.", "section": "Files and Directories", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-files-and-directories"}, {"cmd": "comm -23 &lt;(sort a.txt) &lt;(sort b.txt)", "tip": "Lines in a.txt not in b.txt — a set difference without writing a script for it.", "section": "Files and Directories", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-files-and-directories"}, {"cmd": "tar -czvf archive.tar.gz mydir/", "tip": "Compress a directory into a gzipped tarball — the standard way to bundle and shrink a folder for transfer.", "section": "Files and Directories", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-files-and-directories"}, {"cmd": "tar -xzvf archive.tar.gz", "tip": "Extract it back — reverses the tar step above, unpacking the archive into files again.", "section": "Files and Directories", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-files-and-directories"}, {"cmd": "ln -s /path/to/target linkname", "tip": "Create a symlink — a pointer to another path, not a copy of its contents.", "section": "Files and Directories", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-files-and-directories"}, {"cmd": "stat file.txt", "tip": "Detailed metadata: size, timestamps, inode, permissions — more than ls -l shows in one line.", "section": "Files and Directories", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-files-and-directories"}, {"cmd": "readlink -f symlink", "tip": "Resolve a symlink to its final real path — follows a chain of links to where they actually point.", "section": "Files and Directories", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-files-and-directories"}, {"cmd": "touch newfile.txt", "tip": "Create an empty file, or bump mtime on an existing one — the classic use for confirming a script actually ran.", "section": "Files and Directories", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-files-and-directories"}, {"cmd": "find . -type f -exec md5sum {} \\; | sort | uniq -w32 -d", "tip": "Find duplicate files by content hash across a directory tree — catches true duplicates even with different filenames.", "section": "Files and Directories", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-files-and-directories"}, {"cmd": "rsync -avz --delete src/ dst/", "tip": "Mirror src into dst exactly, removing anything in dst that's not in src — destructive, dry-run first.", "section": "Files and Directories", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-files-and-directories"}, {"cmd": "tar --exclude='*.log' -czvf clean.tar.gz mydir/", "tip": "Archive while excluding a pattern — avoids bundling logs/junk that would just bloat the archive.", "section": "Files and Directories", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-files-and-directories"}, {"cmd": "chmod --reference=file1 file2", "tip": "Copy permissions from one file to another — replicate a known-good config instead of setting bits manually.", "section": "Permissions", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-permissions"}, {"cmd": "getfacl file / setfacl -m u:name:rwx file", "tip": "Fine-grained ACLs beyond owner/group/other — grant access to a specific extra user without changing group ownership.", "section": "Permissions", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-permissions"}, {"cmd": "chattr +i file", "tip": "Make a file immutable — even root can't delete or modify it without unsetting this attribute first.", "section": "Permissions", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-permissions"}, {"cmd": "find / -perm -4000 2&gt;/dev/null", "tip": "Find every SUID binary — useful in a security review.", "section": "Permissions", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-permissions"}, {"cmd": "sudo -l", "tip": "What you're actually allowed to sudo — confirms real permissions instead of assuming from the sudoers file alone.", "section": "Permissions", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-permissions"}, {"cmd": "chown -R user:group /path/to/dir", "tip": "Change ownership recursively for a whole directory tree — the standard fix after copying files in as the wrong user.", "section": "Permissions", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-permissions"}, {"cmd": "umask", "tip": "Current default permission mask for newly created files — explains why new files come out with certain permissions.", "section": "Permissions", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-permissions"}, {"cmd": "umask 022", "tip": "Set the default mask for this shell session — changes permissions on files created from here on, not existing ones.", "section": "Permissions", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-permissions"}, {"cmd": "id username", "tip": "UID, GID, and every group a user belongs to — confirms actual group membership, not just what you assume.", "section": "Permissions", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-permissions"}, {"cmd": "groups username", "tip": "Just the group membership, shorter form — same info as id, less to parse.", "section": "Permissions", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-permissions"}, {"cmd": "find / -perm -2000 2&gt;/dev/null", "tip": "Find every SGID binary — same security-review use case as SUID, different bit.", "section": "Permissions", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-permissions"}, {"cmd": "getent passwd username", "tip": "Confirm a user exists and see their shell/home — works with LDAP/NIS too.", "section": "Permissions", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-permissions"}, {"cmd": "visudo -c", "tip": "Validate /etc/sudoers syntax before it locks you out — always run this after any manual sudoers edit.", "section": "Permissions", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-permissions"}, {"cmd": "ssh -J bastion user@internal-host", "tip": "Jump host in one line — no manual tunnel setup needed to reach a host behind another.", "section": "SSH", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-ssh"}, {"cmd": "ssh -N -L 8080:localhost:80 user@host", "tip": "Local port forward, no shell — great for reaching internal dashboards.", "section": "SSH", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-ssh"}, {"cmd": "ssh -N -D 1080 user@host", "tip": "SOCKS proxy through a single host — routes arbitrary traffic through one SSH connection.", "section": "SSH", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-ssh"}, {"cmd": "ssh-copy-id user@host", "tip": "Push your key without manual cat/append — handles the remote authorized_keys file correctly in one step.", "section": "SSH", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-ssh"}, {"cmd": "scp file.txt user@host:/remote/path/", "tip": "Copy a file to a remote host — the standard one-off file transfer over SSH.", "section": "SSH", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-ssh"}, {"cmd": "scp -r localdir/ user@host:/remote/path/", "tip": "Recursive copy of a directory — same as scp for a single file, but for a whole tree.", "section": "SSH", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-ssh"}, {"cmd": "sftp user@host", "tip": "Interactive file transfer session — browse and transfer files without a fixed source/destination up front.", "section": "SSH", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-ssh"}, {"cmd": "rsync -avz -e ssh src/ user@host:/dst/", "tip": "Rsync over SSH — resumable, only transfers diffs.", "section": "SSH", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-ssh"}, {"cmd": "ssh-add ~/.ssh/id_ed25519", "tip": "Load a key into the running ssh-agent — stop retyping its passphrase for every new connection.", "section": "SSH", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-ssh"}, {"cmd": "ssh-add -l", "tip": "List keys currently loaded in the agent — confirms which identity will actually be offered.", "section": "SSH", "topic": "Linux", "page": "linux/index.html", "anchor": "linux-ssh"}, {"cmd": "du -sh --max-depth=1 / 2&gt;/dev/null | sort -rh | head", "tip": "Which top-level directory is actually growing — narrows a full-disk hunt before you go file by file.", "section": "Specific problems", "topic": "Linux", "page": "linux/index.html", "anchor": "specific-problems"}, {"cmd": "lsof +D /var/log 2&gt;/dev/null | awk '{print $NF}' | sort -u", "tip": "Check for deleted-but-still-open files first — df and du disagreeing is the classic sign.", "section": "Specific problems", "topic": "Linux", "page": "linux/index.html", "anchor": "specific-problems"}, {"cmd": "ps -eo pid,ppid,stat,cmd | grep 'Z'", "tip": "Zombie processes (state Z) — these can't be killed directly, the problem is the parent not reaping them.", "section": "Specific problems", "topic": "Linux", "page": "linux/index.html", "anchor": "specific-problems"}, {"cmd": "kill -9 &lt;parent_pid&gt;", "tip": "Killing the parent usually clears it — if the parent is PID 1, only a reboot fixes it.", "section": "Specific problems", "topic": "Linux", "page": "linux/index.html", "anchor": "specific-problems"}, {"cmd": "dmesg -T | grep -i &quot;out of memory&quot;", "tip": "Confirm it was actually the OOM killer, not a crash.", "section": "Specific problems", "topic": "Linux", "page": "linux/index.html", "anchor": "specific-problems"}, {"cmd": "journalctl -k | grep -i oom", "tip": "OOM killer's own kernel log entries — works on any systemd distro, not just Debian/Ubuntu-specific /var/log/syslog.", "section": "Specific problems", "topic": "Linux", "page": "linux/index.html", "anchor": "specific-problems"}, {"cmd": "bash -n script.sh", "tip": "Syntax check only — catches a typo before it fails halfway through an actual run.", "section": "Script Execution", "topic": "Linux", "page": "linux/bash/index.html", "anchor": "bash-script-execution"}, {"cmd": "bash -x script.sh", "tip": "Trace every command as it executes — see exactly what ran and with what values, not just the final result.", "section": "Script Execution", "topic": "Linux", "page": "linux/bash/index.html", "anchor": "bash-script-execution"}, {"cmd": "set -euo pipefail", "tip": "Fail fast: exit on error, unset var, or failed pipe stage — put this at the top of every script.", "section": "Script Execution", "topic": "Linux", "page": "linux/bash/index.html", "anchor": "bash-script-execution"}, {"cmd": "bash script.sh arg1 arg2", "tip": "Positional args are available as $1 $2 — all of them as $@, and $# gives you the count.", "section": "Script Execution", "topic": "Linux", "page": "linux/bash/index.html", "anchor": "bash-script-execution"}, {"cmd": "source ./env.sh", "tip": "Run a script in the current shell — exports persist afterward, unlike a subshell.", "section": "Script Execution", "topic": "Linux", "page": "linux/bash/index.html", "anchor": "bash-script-execution"}, {"cmd": "chmod +x script.sh", "tip": "Make a script directly executable — lets you run it as ./script.sh instead of bash script.sh.", "section": "Script Execution", "topic": "Linux", "page": "linux/bash/index.html", "anchor": "bash-script-execution"}, {"cmd": "#!/usr/bin/env bash", "tip": "Portable shebang — finds bash via PATH instead of assuming /bin/bash exists at that exact path.", "section": "Script Execution", "topic": "Linux", "page": "linux/bash/index.html", "anchor": "bash-script-execution"}, {"cmd": "my_func() { echo &quot;arg1=$1&quot;; return 0; }", "tip": "Function definition — $1 etc. are the function's own args, not the script's.", "section": "Script Execution", "topic": "Linux", "page": "linux/bash/index.html", "anchor": "bash-script-execution"}, {"cmd": "local var=&quot;value&quot;", "tip": "Inside a function, scopes a variable to that function only — always use this over a bare assignment in functions.", "section": "Script Execution", "topic": "Linux", "page": "linux/bash/index.html", "anchor": "bash-script-execution"}, {"cmd": "arr=(one two three); echo &quot;${arr[1]}&quot;", "tip": "Array literal + zero-indexed access — prints &quot;two&quot;.", "section": "Script Execution", "topic": "Linux", "page": "linux/bash/index.html", "anchor": "bash-script-execution"}, {"cmd": "for item in &quot;${arr[@]}&quot;; do echo &quot;$item&quot;; done", "tip": "Iterate an array safely — quoting survives spaces inside elements that an unquoted loop would split incorrectly.", "section": "Script Execution", "topic": "Linux", "page": "linux/bash/index.html", "anchor": "bash-script-execution"}, {"cmd": "set -x", "tip": "Turn tracing on mid-script — enable set -x only where the suspicious code actually starts.", "section": "Debugging", "topic": "Linux", "page": "linux/bash/index.html", "anchor": "bash-debugging"}, {"cmd": "set +x", "tip": "Turn it back off — brackets tracing to only the suspicious block instead of flooding the whole run.", "section": "Debugging", "topic": "Linux", "page": "linux/bash/index.html", "anchor": "bash-debugging"}, {"cmd": "trap 'echo &quot;failed at line $LINENO&quot;' ERR", "tip": "Know exactly where a script died — a trap on ERR reports the line number instead of leaving you guessing.", "section": "Debugging", "topic": "Linux", "page": "linux/bash/index.html", "anchor": "bash-debugging"}, {"cmd": "PS4='+ $(date &quot;+%T&quot;) ${BASH_SOURCE}:${LINENO}: '", "tip": "Timestamped trace output when combined with set -x — shows how long each step actually took, not just what ran.", "section": "Debugging", "topic": "Linux", "page": "linux/bash/index.html", "anchor": "bash-debugging"}, {"cmd": "exec 5&gt;debug.log; BASH_XTRACEFD=5; set -x", "tip": "Send xtrace output to its own file descriptor/file instead of stderr — lets you debug a script without its trace lines mixing into real stderr output that other tools might parse.", "section": "Debugging", "topic": "Linux", "page": "linux/bash/index.html", "anchor": "bash-debugging"}, {"cmd": "shellcheck script.sh", "tip": "Static analysis — catches quoting bugs, unused vars, and common mistakes before you run anything.", "section": "Debugging", "topic": "Linux", "page": "linux/bash/index.html", "anchor": "bash-debugging"}, {"cmd": "bash -u script.sh", "tip": "Treat unset variables as an error and exit — catches typos in variable names.", "section": "Debugging", "topic": "Linux", "page": "linux/bash/index.html", "anchor": "bash-debugging"}, {"cmd": "echo &quot;DEBUG: var=$var&quot; &gt;&amp;2", "tip": "A poor man's breakpoint — send debug output to stderr so it doesn't pollute stdout a caller might be parsing.", "section": "Debugging", "topic": "Linux", "page": "linux/bash/index.html", "anchor": "bash-debugging"}, {"cmd": "long_task &amp;", "tip": "Run in background — doesn't block the terminal until the command finishes.", "section": "Background Jobs", "topic": "Linux", "page": "linux/bash/index.html", "anchor": "bash-background-jobs"}, {"cmd": "jobs -l", "tip": "List background jobs with PIDs — confirms what's actually running before fg/kill-ing the wrong one.", "section": "Background Jobs", "topic": "Linux", "page": "linux/bash/index.html", "anchor": "bash-background-jobs"}, {"cmd": "fg %1 / bg %1", "tip": "Bring to foreground / resume in background — reattach or unpause a specific job by number.", "section": "Background Jobs", "topic": "Linux", "page": "linux/bash/index.html", "anchor": "bash-background-jobs"}, {"cmd": "disown -a", "tip": "Detach all jobs from this shell — they survive shell exit.", "section": "Background Jobs", "topic": "Linux", "page": "linux/bash/index.html", "anchor": "bash-background-jobs"}, {"cmd": "kill %1", "tip": "Kill background job 1 by job number — no need to look up the PID first.", "section": "Background Jobs", "topic": "Linux", "page": "linux/bash/index.html", "anchor": "bash-background-jobs"}, {"cmd": "wait %1", "tip": "Block until job 1 finishes — useful before reading its output or exit code, which aren't ready until it completes.", "section": "Background Jobs", "topic": "Linux", "page": "linux/bash/index.html", "anchor": "bash-background-jobs"}, {"cmd": "wait -n", "tip": "Block until ANY background job finishes (not all) — good for basic parallel task management.", "section": "Background Jobs", "topic": "Linux", "page": "linux/bash/index.html", "anchor": "bash-background-jobs"}, {"cmd": "$!", "tip": "PID of the most recently backgrounded process — capture it right after the &amp; line.", "section": "Background Jobs", "topic": "Linux", "page": "linux/bash/index.html", "anchor": "bash-background-jobs"}, {"cmd": "flock -n /tmp/job.lock -c &quot;./script.sh&quot;", "tip": "Prevent overlapping cron runs — non-blocking, exits if already locked.", "section": "Locks and Timeouts", "topic": "Linux", "page": "linux/bash/index.html", "anchor": "bash-locks-and-timeouts"}, {"cmd": "timeout 30 curl https://slow-service", "tip": "Kill a hung command after 30s — prevents a script from hanging forever on one stuck step.", "section": "Locks and Timeouts", "topic": "Linux", "page": "linux/bash/index.html", "anchor": "bash-locks-and-timeouts"}, {"cmd": "timeout -k5 30 ./script.sh", "tip": "SIGTERM at 30s, SIGKILL 5s later if it ignores the first — gives the process a chance to clean up before forcing it.", "section": "Locks and Timeouts", "topic": "Linux", "page": "linux/bash/index.html", "anchor": "bash-locks-and-timeouts"}, {"cmd": "flock -w 30 /tmp/job.lock -c &quot;./script.sh&quot;", "tip": "Wait up to 30s for the lock instead of failing immediately — useful when a brief overlap with another run is expected.", "section": "Locks and Timeouts", "topic": "Linux", "page": "linux/bash/index.html", "anchor": "bash-locks-and-timeouts"}, {"cmd": "exec 200&gt;/tmp/job.lock; flock -n 200 || exit 1", "tip": "Hold a lock for the script's whole lifetime via a file descriptor — released automatically on exit.", "section": "Locks and Timeouts", "topic": "Linux", "page": "linux/bash/index.html", "anchor": "bash-locks-and-timeouts"}, {"cmd": "timeout --preserve-status 30 ./script.sh", "tip": "Propagate the wrapped command's actual exit code — otherwise a caller only sees timeout's own 124, not what actually failed.", "section": "Locks and Timeouts", "topic": "Linux", "page": "linux/bash/index.html", "anchor": "bash-locks-and-timeouts"}, {"cmd": "bash -x ./script.sh 2&gt;&amp;1 | tail -30", "tip": "See the last commands executed before it died — the actual failing line is usually right before the output stops.", "section": "Health check", "topic": "Linux", "page": "linux/bash/index.html", "anchor": "health-check"}, {"cmd": "echo $?", "tip": "Exit code of the last command — nonzero means something failed silently.", "section": "Health check", "topic": "Linux", "page": "linux/bash/index.html", "anchor": "health-check"}, {"cmd": "env -i /bin/bash --noprofile --norc ./script.sh", "tip": "Run with a stripped-down environment, closer to what cron actually provides.", "section": "Health check", "topic": "Linux", "page": "linux/bash/index.html", "anchor": "health-check"}, {"cmd": "which &lt;command_used_in_script&gt;", "tip": "Confirm the command is on PATH — cron's PATH is much shorter than an interactive shell's.", "section": "Health check", "topic": "Linux", "page": "linux/bash/index.html", "anchor": "health-check"}, {"cmd": "ip -br a", "tip": "Brief address list, one line per interface — a fast readable summary instead of ifconfig's verbose output.", "section": "Interfaces", "topic": "Linux", "page": "linux/networking/index.html", "anchor": "networking-interfaces"}, {"cmd": "ip link show", "tip": "Link state (UP/DOWN) and MTU — confirms the interface is actually up before checking anything higher-level.", "section": "Interfaces", "topic": "Linux", "page": "linux/networking/index.html", "anchor": "networking-interfaces"}, {"cmd": "ethtool eth0", "tip": "Link speed/duplex — check this when &quot;the network feels slow&quot;.", "section": "Interfaces", "topic": "Linux", "page": "linux/networking/index.html", "anchor": "networking-interfaces"}, {"cmd": "ip addr add 10.0.0.5/24 dev eth0", "tip": "Add an IP to an interface — temporary, lost on reboot unless persisted.", "section": "Interfaces", "topic": "Linux", "page": "linux/networking/index.html", "anchor": "networking-interfaces"}, {"cmd": "ip link set eth0 up", "tip": "Bring an interface up — required after adding an address or restoring a disabled interface.", "section": "Interfaces", "topic": "Linux", "page": "linux/networking/index.html", "anchor": "networking-interfaces"}, {"cmd": "ip link set eth0 down", "tip": "Bring it down — the opposite of the line above, useful before reconfiguring an interface.", "section": "Interfaces", "topic": "Linux", "page": "linux/networking/index.html", "anchor": "networking-interfaces"}, {"cmd": "ethtool -S eth0", "tip": "Interface statistics — errors, drops, collisions, useful for chasing packet loss.", "section": "Interfaces", "topic": "Linux", "page": "linux/networking/index.html", "anchor": "networking-interfaces"}, {"cmd": "ss -tulnp", "tip": "Listening TCP/UDP + PID — the modern replacement for netstat, faster on systems with many connections.", "section": "Ports", "topic": "Linux", "page": "linux/networking/index.html", "anchor": "networking-ports"}, {"cmd": "lsof -i :443", "tip": "What's bound to a specific port — confirms exactly what's using it before you assume nothing is.", "section": "Ports", "topic": "Linux", "page": "linux/networking/index.html", "anchor": "networking-ports"}, {"cmd": "fuser -k 8080/tcp", "tip": "Kill whatever's holding a port — a fast fix for &quot;address already in use&quot; without hunting for the PID first.", "section": "Ports", "topic": "Linux", "page": "linux/networking/index.html", "anchor": "networking-ports"}, {"cmd": "ss -tan state established", "tip": "Only established TCP connections — filters out listeners and time-wait noise you usually don't care about.", "section": "Ports", "topic": "Linux", "page": "linux/networking/index.html", "anchor": "networking-ports"}, {"cmd": "ss -s", "tip": "Socket summary counts by state — quick overview of connection health.", "section": "Ports", "topic": "Linux", "page": "linux/networking/index.html", "anchor": "networking-ports"}, {"cmd": "netstat -tulnp", "tip": "The older equivalent of ss -tulnp — still common on minimal images that don't have ss installed.", "section": "Ports", "topic": "Linux", "page": "linux/networking/index.html", "anchor": "networking-ports"}, {"cmd": "dig +short host.example.com", "tip": "Just the answer, no noise — dig's default output is verbose, this strips it to the one line you actually want.", "section": "DNS", "topic": "Linux", "page": "linux/networking/index.html", "anchor": "networking-dns"}, {"cmd": "dig +trace host.example.com", "tip": "Walk the full resolution chain, root to authoritative — shows exactly which server answered at each step.", "section": "DNS", "topic": "Linux", "page": "linux/networking/index.html", "anchor": "networking-dns"}, {"cmd": "resolvectl query host.example.com", "tip": "On systemd-resolved hosts, shows which resolver actually answered — confirms which of possibly several configured resolvers responded.", "section": "DNS", "topic": "Linux", "page": "linux/networking/index.html", "anchor": "networking-dns"}, {"cmd": "dig @8.8.8.8 host.example.com", "tip": "Query a specific resolver directly — bypasses local cache, confirms what that resolver actually has.", "section": "DNS", "topic": "Linux", "page": "linux/networking/index.html", "anchor": "networking-dns"}, {"cmd": "host host.example.com", "tip": "Simplest possible DNS lookup — minimal output when you just need the answer, not the full dig report.", "section": "DNS", "topic": "Linux", "page": "linux/networking/index.html", "anchor": "networking-dns"}, {"cmd": "nslookup host.example.com", "tip": "Older tool, still common in scripts and on Windows-adjacent teams — same job as dig, different output format.", "section": "DNS", "topic": "Linux", "page": "linux/networking/index.html", "anchor": "networking-dns"}, {"cmd": "getent hosts host.example.com", "tip": "Resolves via the same path applications use — respects /etc/nsswitch.conf, not just DNS.", "section": "DNS", "topic": "Linux", "page": "linux/networking/index.html", "anchor": "networking-dns"}, {"cmd": "cat /etc/resolv.conf", "tip": "Which nameservers this host is actually configured to use — confirms the real config before assuming DNS is misconfigured.", "section": "DNS", "topic": "Linux", "page": "linux/networking/index.html", "anchor": "networking-dns"}, {"cmd": "mtr host.example.com", "tip": "Ping + traceroute combined, live — best first tool for &quot;is it the network&quot;.", "section": "Connectivity", "topic": "Linux", "page": "linux/networking/index.html", "anchor": "networking-connectivity"}, {"cmd": "nc -zv host 443", "tip": "Quick TCP port check — no telnet needed, nc does the same job and is more commonly preinstalled now.", "section": "Connectivity", "topic": "Linux", "page": "linux/networking/index.html", "anchor": "networking-connectivity"}, {"cmd": "tcpdump -i any port 443 -w cap.pcap", "tip": "Capture for later analysis in Wireshark — save traffic now, dig into it properly later with a GUI.", "section": "Connectivity", "topic": "Linux", "page": "linux/networking/index.html", "anchor": "networking-connectivity"}, {"cmd": "tcpdump -i eth0 -nn host 10.0.0.5 and port 443", "tip": "Filtered live capture, no DNS lookups — faster and cleaner output than letting tcpdump resolve every address.", "section": "Connectivity", "topic": "Linux", "page": "linux/networking/index.html", "anchor": "networking-connectivity"}, {"cmd": "mtr --report --report-cycles 10 host.example.com", "tip": "Non-interactive report mode — 10 cycles then exit, perfect for pasting into a ticket or a script instead of the live TUI view.", "section": "Connectivity", "topic": "Linux", "page": "linux/networking/index.html", "anchor": "networking-connectivity"}, {"cmd": "curl -o /dev/null -s -w '%{http_code} %{time_total}s\\n' https://host", "tip": "Status code + total time, nothing else — a minimal health check without the full response body.", "section": "HTTP and curl", "topic": "Linux", "page": "linux/networking/index.html", "anchor": "networking-http-and-curl"}, {"cmd": "curl -w &quot;@curl-format.txt&quot; -o /dev/null -s https://host", "tip": "Full timing breakdown — DNS, connect, TLS, TTFB, pinpoints exactly which phase is slow.", "section": "HTTP and curl", "topic": "Linux", "page": "linux/networking/index.html", "anchor": "networking-http-and-curl"}, {"cmd": "curl -kv https://host 2&gt;&amp;1 | grep -A2 'subject\\|expire'", "tip": "Quick cert subject + expiry check — no need to drop into openssl s_client for a fast look.", "section": "HTTP and curl", "topic": "Linux", "page": "linux/networking/index.html", "anchor": "networking-http-and-curl"}, {"cmd": "curl -I https://host", "tip": "Headers only — a HEAD request, fast check without downloading the full body.", "section": "HTTP and curl", "topic": "Linux", "page": "linux/networking/index.html", "anchor": "networking-http-and-curl"}, {"cmd": "curl -L https://host", "tip": "Follow redirects — plain curl stops at the first 3xx by default.", "section": "HTTP and curl", "topic": "Linux", "page": "linux/networking/index.html", "anchor": "networking-http-and-curl"}, {"cmd": "curl -X POST -d '{&quot;key&quot;:&quot;value&quot;}' -H &quot;Content-Type: application/json&quot; https://host/api", "tip": "Send a JSON POST body — the standard way to hit a JSON API from the command line.", "section": "HTTP and curl", "topic": "Linux", "page": "linux/networking/index.html", "anchor": "networking-http-and-curl"}, {"cmd": "curl -u user:pass https://host", "tip": "Sends HTTP Basic Authentication credentials with the request — the -u shorthand instead of building the header by hand.", "section": "HTTP and curl", "topic": "Linux", "page": "linux/networking/index.html", "anchor": "networking-http-and-curl"}, {"cmd": "ss -tulnp | grep &lt;port&gt;", "tip": "Find what's already bound to the port — the actual fix is identifying the conflicting process, not guessing.", "section": "Health check", "topic": "Linux", "page": "linux/networking/index.html", "anchor": "health-check"}, {"cmd": "kill &lt;pid_from_above&gt;", "tip": "Or reconfigure one of the two services to use a different port — the alternative to killing whatever's already bound.", "section": "Health check", "topic": "Linux", "page": "linux/networking/index.html", "anchor": "health-check"}, {"cmd": "cat /etc/resolv.conf", "tip": "Confirm nameservers are actually configured — an empty resolv.conf explains DNS failures immediately.", "section": "Health check", "topic": "Linux", "page": "linux/networking/index.html", "anchor": "health-check"}, {"cmd": "dig @8.8.8.8 &lt;hostname&gt;", "tip": "Bypass the local resolver entirely — if this works, the problem is local DNS config, not the network.", "section": "Health check", "topic": "Linux", "page": "linux/networking/index.html", "anchor": "health-check"}, {"cmd": "systemd-resolve --status", "tip": "On systemd-resolved hosts, shows which resolver is actually active per interface — resolv.conf alone can be misleading here.", "section": "Health check", "topic": "Linux", "page": "linux/networking/index.html", "anchor": "health-check"}, {"cmd": "tail -f /var/log/myapp/app.log", "tip": "Follow a single log file live — watch new lines appear as they're written.", "section": "Logs", "topic": "Linux", "page": "linux/logs/index.html", "anchor": ""}, {"cmd": "tail -f /var/log/myapp/*.log", "tip": "Follow multiple files at once, each line prefixed with its filename — correlate events across services without switching terminals.", "section": "Logs", "topic": "Linux", "page": "linux/logs/index.html", "anchor": ""}, {"cmd": "grep -i &quot;error&quot; /var/log/myapp/app.log", "tip": "Case-insensitive search in a plain log file — catches a match regardless of how it was capitalized.", "section": "Logs", "topic": "Linux", "page": "linux/logs/index.html", "anchor": ""}, {"cmd": "grep -rn &quot;connection refused&quot; /var/log/myapp/", "tip": "Recursive search across a whole log directory, with line numbers — find a match without knowing which file it's in.", "section": "Logs", "topic": "Linux", "page": "linux/logs/index.html", "anchor": ""}, {"cmd": "zgrep &quot;timeout&quot; /var/log/myapp/app.log.2.gz", "tip": "Search inside a rotated, gzip-compressed log — no need to manually decompress it first.", "section": "Logs", "topic": "Linux", "page": "linux/logs/index.html", "anchor": ""}, {"cmd": "find /var/log -name &quot;*.log&quot; -mtime -1", "tip": "Every log file modified in the last 24h, across the system — finds active logs you don't already know the location of.", "section": "Logs", "topic": "Linux", "page": "linux/logs/index.html", "anchor": ""}, {"cmd": "find /var/log -name &quot;*.log&quot; -size +100M", "tip": "Find unexpectedly large log files eating disk — the fast way to spot what's actually filling /var/log.", "section": "Logs", "topic": "Linux", "page": "linux/logs/index.html", "anchor": ""}, {"cmd": "awk '/2026-09-10 14:0/,/2026-09-10 14:1/' app.log", "tip": "Print only lines within a time window — precise on huge logs where grep -A/-B isn't.", "section": "Logs", "topic": "Linux", "page": "linux/logs/index.html", "anchor": ""}, {"cmd": "journalctl --since &quot;10 minutes ago&quot; -o cat", "tip": "Check whether an app is actually logging to the journal instead of a file — confirms you're looking in the right place at all.", "section": "Logs", "topic": "Linux", "page": "linux/logs/index.html", "anchor": ""}, {"cmd": "head -n 100 app.log", "tip": "First 100 lines — useful for checking a log's format/header before writing a real filter.", "section": "Logs", "topic": "Linux", "page": "linux/logs/index.html", "anchor": ""}, {"cmd": "grep -A5 -B5 &quot;OutOfMemoryError&quot; app.log", "tip": "5 lines of context before and after a match — the surrounding lines are usually what actually explains it.", "section": "Logs", "topic": "Linux", "page": "linux/logs/index.html", "anchor": ""}, {"cmd": "tail -n +1 -f app.log | grep --line-buffered &quot;ERROR&quot;", "tip": "Follow a file live, filtered to error lines — --line-buffered avoids grep batching when piped.", "section": "Logs", "topic": "Linux", "page": "linux/logs/index.html", "anchor": ""}, {"cmd": "zcat app.log.1.gz app.log.2.gz | grep &quot;user_id=12345&quot;", "tip": "Search across several rotated archives at once, in the order they happened — reconstructs a timeline that spans multiple rotated files.", "section": "Logs", "topic": "Linux", "page": "linux/logs/index.html", "anchor": ""}, {"cmd": ": &gt; /var/log/myapp/app.log", "tip": "Truncate a live log file in place, safe even while a process still has it open — rm would just hide the space until the process exits.", "section": "Logs", "topic": "Linux", "page": "linux/logs/index.html", "anchor": ""}, {"cmd": "cat /etc/logrotate.d/myapp", "tip": "See how a specific app's rotation is configured — size/age thresholds, compression, retention count.", "section": "Logs", "topic": "Linux", "page": "linux/logs/index.html", "anchor": ""}, {"cmd": "logrotate -d /etc/logrotate.d/myapp", "tip": "Dry-run: shows what WOULD happen — confirms the rotation config is correct before it actually runs for real.", "section": "Logs", "topic": "Linux", "page": "linux/logs/index.html", "anchor": ""}, {"cmd": "logrotate -f /etc/logrotate.d/myapp", "tip": "Force an out-of-cycle rotation right now — useful as an emergency move before a disk actually fills up.", "section": "Logs", "topic": "Linux", "page": "linux/logs/index.html", "anchor": ""}, {"cmd": "lsof -p &lt;pid&gt; | grep -i log", "tip": "List open files for the process — its log file(s) show up here even with a nonstandard path.", "section": "Troubleshooting", "topic": "Linux", "page": "linux/logs/index.html", "anchor": "troubleshooting"}, {"cmd": "find / -xdev -name &quot;*.log&quot; -newer /tmp -mmin -5 2&gt;/dev/null", "tip": "Files touched in the last 5 minutes — catches an active log you don't know the location of.", "section": "Troubleshooting", "topic": "Linux", "page": "linux/logs/index.html", "anchor": "troubleshooting"}, {"cmd": ": &gt; /var/log/myapp/app.log", "tip": "Truncate in place, safe even if a process still has it open — see the Enhanced note above.", "section": "Troubleshooting", "topic": "Linux", "page": "linux/logs/index.html", "anchor": "troubleshooting"}, {"cmd": "logrotate -f /etc/logrotate.d/myapp", "tip": "Force rotation now — then check why it didn't run on schedule.", "section": "Troubleshooting", "topic": "Linux", "page": "linux/logs/index.html", "anchor": "troubleshooting"}, {"cmd": "grep -F &quot;exact string&quot; bigfile.log", "tip": "F (fixed string) skips regex parsing — much faster when you're not actually using regex features.", "section": "Troubleshooting", "topic": "Linux", "page": "linux/logs/index.html", "anchor": "troubleshooting"}, {"cmd": "rg &quot;pattern&quot; bigfile.log", "tip": "Ripgrep, if available — multithreaded and typically far faster than grep on large files.", "section": "Troubleshooting", "topic": "Linux", "page": "linux/logs/index.html", "anchor": "troubleshooting"}, {"cmd": "journalctl -u myservice -f", "tip": "Follow, like tail -f but for the journal — watch a service's log live as it writes.", "section": "Systemd", "topic": "Linux", "page": "linux/systemd/index.html", "anchor": ""}, {"cmd": "journalctl -p err -b", "tip": "Errors only, this boot — filters out noise, scoped to since the last restart.", "section": "Systemd", "topic": "Linux", "page": "linux/systemd/index.html", "anchor": ""}, {"cmd": "journalctl -k", "tip": "Kernel messages only — the journal-native equivalent of dmesg, same data different tool.", "section": "Systemd", "topic": "Linux", "page": "linux/systemd/index.html", "anchor": ""}, {"cmd": "journalctl --disk-usage", "tip": "How much space the journal itself is using — check before assuming disk pressure is from something else.", "section": "Systemd", "topic": "Linux", "page": "linux/systemd/index.html", "anchor": ""}, {"cmd": "journalctl -o json-pretty -u myservice", "tip": "Structured output, pipeable to jq — parse journal entries programmatically instead of scraping text.", "section": "Systemd", "topic": "Linux", "page": "linux/systemd/index.html", "anchor": ""}, {"cmd": "systemctl list-units --failed", "tip": "Everything currently broken, system-wide, one command — a fast health check before digging into any one service.", "section": "Systemd", "topic": "Linux", "page": "linux/systemd/index.html", "anchor": ""}, {"cmd": "systemctl show myservice -p MainPID -p ActiveState", "tip": "Pull specific properties, scriptable — grab just the fields you need instead of parsing full status output.", "section": "Systemd", "topic": "Linux", "page": "linux/systemd/index.html", "anchor": ""}, {"cmd": "systemd-analyze blame", "tip": "What's slowing down boot, sorted — points straight at the actual bottleneck instead of guessing.", "section": "Systemd", "topic": "Linux", "page": "linux/systemd/index.html", "anchor": ""}, {"cmd": "systemd-analyze critical-chain", "tip": "The actual dependency chain that determines boot time — shows what's waiting on what, not just individual unit times.", "section": "Systemd", "topic": "Linux", "page": "linux/systemd/index.html", "anchor": ""}, {"cmd": "systemctl edit myservice", "tip": "Drop-in override without touching the vendor unit file — survives a package update that would overwrite a direct edit.", "section": "Systemd", "topic": "Linux", "page": "linux/systemd/index.html", "anchor": ""}, {"cmd": "systemctl daemon-reload", "tip": "Required after any unit file change — systemd caches unit definitions, edits won't take effect without this.", "section": "Systemd", "topic": "Linux", "page": "linux/systemd/index.html", "anchor": ""}, {"cmd": "systemctl mask myservice", "tip": "Stronger than disable — prevents even manual start.", "section": "Systemd", "topic": "Linux", "page": "linux/systemd/index.html", "anchor": ""}, {"cmd": "systemctl start myservice", "tip": "Start a stopped service — brings it up immediately, doesn't affect boot-time behavior.", "section": "Systemd", "topic": "Linux", "page": "linux/systemd/index.html", "anchor": ""}, {"cmd": "systemctl stop myservice", "tip": "Stop a running service — takes it down immediately, doesn't affect boot-time behavior.", "section": "Systemd", "topic": "Linux", "page": "linux/systemd/index.html", "anchor": ""}, {"cmd": "systemctl restart myservice", "tip": "Stop then start — a full restart, as opposed to reload which avoids downtime.", "section": "Systemd", "topic": "Linux", "page": "linux/systemd/index.html", "anchor": ""}, {"cmd": "systemctl reload myservice", "tip": "Re-read config without a full restart — avoids downtime, but only works if the service actually supports reload.", "section": "Systemd", "topic": "Linux", "page": "linux/systemd/index.html", "anchor": ""}, {"cmd": "systemctl enable myservice", "tip": "Start automatically on boot — doesn't start it right now, only changes future boot behavior.", "section": "Systemd", "topic": "Linux", "page": "linux/systemd/index.html", "anchor": ""}, {"cmd": "systemctl disable myservice", "tip": "Don't start automatically on boot — doesn't stop it if it's already running now.", "section": "Systemd", "topic": "Linux", "page": "linux/systemd/index.html", "anchor": ""}, {"cmd": "systemctl cat myservice", "tip": "Print the actual unit file(s) in use — including drop-in overrides.", "section": "Systemd", "topic": "Linux", "page": "linux/systemd/index.html", "anchor": ""}, {"cmd": "systemctl list-unit-files --type=service", "tip": "Every known service unit and its enabled/disabled state — a full inventory of what would start on boot.", "section": "Systemd", "topic": "Linux", "page": "linux/systemd/index.html", "anchor": ""}, {"cmd": "systemctl list-timers", "tip": "Every scheduled timer and its next run time — the systemd-native way to see &quot;what's scheduled&quot; instead of grepping crontabs.", "section": "Systemd", "topic": "Linux", "page": "linux/systemd/index.html", "anchor": ""}, {"cmd": "systemctl status mytimer.timer", "tip": "Is a specific timer active and enabled — confirms a scheduled job is actually going to fire.", "section": "Systemd", "topic": "Linux", "page": "linux/systemd/index.html", "anchor": ""}, {"cmd": "journalctl -u mytimer.service", "tip": "A timer's logs live under its paired .service unit — checking the .timer itself won't show the job's actual output.", "section": "Systemd", "topic": "Linux", "page": "linux/systemd/index.html", "anchor": ""}, {"cmd": "systemctl status myservice -l", "tip": "L shows the full text, not truncated — the real error is often cut off without it.", "section": "Troubleshooting", "topic": "Linux", "page": "linux/systemd/index.html", "anchor": "troubleshooting"}, {"cmd": "journalctl -xeu myservice", "tip": "X adds explanatory help text for common failure codes — often explains the fix, not just the error.", "section": "Troubleshooting", "topic": "Linux", "page": "linux/systemd/index.html", "anchor": "troubleshooting"}, {"cmd": "systemctl daemon-reload", "tip": "Required after ANY change to a unit file — systemd caches the old definition otherwise.", "section": "Troubleshooting", "topic": "Linux", "page": "linux/systemd/index.html", "anchor": "troubleshooting"}, {"cmd": "systemctl show myservice -p FragmentPath", "tip": "Confirm which file it's actually reading from — a stray override elsewhere is a common surprise.", "section": "Troubleshooting", "topic": "Linux", "page": "linux/systemd/index.html", "anchor": "troubleshooting"}, {"cmd": "journalctl --disk-usage", "tip": "Confirm it's actually the journal eating disk — before vacuuming, make sure you're fixing the right thing.", "section": "Troubleshooting", "topic": "Linux", "page": "linux/systemd/index.html", "anchor": "troubleshooting"}, {"cmd": "journalctl --vacuum-size=500M", "tip": "Shrink the journal to a target size — oldest entries drop first, recent history is preserved.", "section": "Troubleshooting", "topic": "Linux", "page": "linux/systemd/index.html", "anchor": "troubleshooting"}, {"cmd": "journalctl --vacuum-time=7d", "tip": "Or keep by age instead of size — whichever matches your retention need.", "section": "Troubleshooting", "topic": "Linux", "page": "linux/systemd/index.html", "anchor": "troubleshooting"}, {"cmd": "uptime", "tip": "Load average — compare to core count, not to 1.0.", "section": "Performance", "topic": "Linux", "page": "linux/performance/index.html", "anchor": ""}, {"cmd": "vmstat 1", "tip": "Check the 'r' (run queue) and 'wa' (I/O wait) columns — 'r' over core count means CPU-bound, high 'wa' means I/O-bound.", "section": "Performance", "topic": "Linux", "page": "linux/performance/index.html", "anchor": ""}, {"cmd": "perf top", "tip": "Live, per-function CPU profiling — needs perf installed, shows exactly which function is hot in real time.", "section": "Performance", "topic": "Linux", "page": "linux/performance/index.html", "anchor": ""}, {"cmd": "strace -c ./binary", "tip": "Syscall summary — which syscalls dominate, and how many.", "section": "Performance", "topic": "Linux", "page": "linux/performance/index.html", "anchor": ""}, {"cmd": "iostat -xz 1", "tip": "%util near 100 on a device means that's your actual bottleneck, not just a busy-looking number.", "section": "Performance", "topic": "Linux", "page": "linux/performance/index.html", "anchor": ""}, {"cmd": "sar -q 1 5", "tip": "Historical load average + run queue length — needs sysstat, shows the trend instead of a single snapshot.", "section": "Performance", "topic": "Linux", "page": "linux/performance/index.html", "anchor": ""}, {"cmd": "dstat", "tip": "Combined CPU/disk/net/memory view, one screen — a friendlier vmstat+iostat+ifstat.", "section": "Performance", "topic": "Linux", "page": "linux/performance/index.html", "anchor": ""}, {"cmd": "htop", "tip": "Interactive top with per-core bars and a tree view — easier mouse-driven sorting than plain top.", "section": "Performance", "topic": "Linux", "page": "linux/performance/index.html", "anchor": ""}, {"cmd": "pidstat -p &lt;pid&gt; 1", "tip": "Per-process CPU/context-switch breakdown over time — narrower and clearer than top when you already know which process to watch.", "section": "Performance", "topic": "Linux", "page": "linux/performance/index.html", "anchor": ""}, {"cmd": "perf record -p &lt;pid&gt; -g -- sleep 10", "tip": "Profile one process for 10s with call graphs — then `perf report` to see hot functions.", "section": "Performance", "topic": "Linux", "page": "linux/performance/index.html", "anchor": ""}, {"cmd": "perf stat ./binary", "tip": "Summary counters for one run — instructions, cache misses, context switches, branch mispredicts.", "section": "Performance", "topic": "Linux", "page": "linux/performance/index.html", "anchor": ""}, {"cmd": "iotop -o", "tip": "Like top but for disk I/O — -o hides processes doing zero I/O, so only active ones show.", "section": "Performance", "topic": "Linux", "page": "linux/performance/index.html", "anchor": ""}, {"cmd": "vmstat 1 5", "tip": "Check 'r' (run queue) and 'wa' (I/O wait) columns — a slowdown can be system-wide contention, not one process.", "section": "Troubleshooting", "topic": "Linux", "page": "linux/performance/index.html", "anchor": "troubleshooting"}, {"cmd": "mpstat -P ALL 1", "tip": "Per-core breakdown — one pegged core hiding behind an average that looks fine is a common trap.", "section": "Troubleshooting", "topic": "Linux", "page": "linux/performance/index.html", "anchor": "troubleshooting"}, {"cmd": "ps -eo stat,pid,cmd | grep &quot;^D&quot;", "tip": "D-state processes count toward load average but not CPU% — usually I/O-bound.", "section": "Troubleshooting", "topic": "Linux", "page": "linux/performance/index.html", "anchor": "troubleshooting"}, {"cmd": "iostat -xz 1", "tip": "Confirm which device those D-state processes are actually waiting on — narrows a stuck process down to a specific disk.", "section": "Troubleshooting", "topic": "Linux", "page": "linux/performance/index.html", "anchor": "troubleshooting"}, {"cmd": "watch -n5 'ps -eo pid,cmd,%mem,rss --sort=-rss | head -10'", "tip": "Watch top memory consumers over time — a steadily climbing RSS on one process is the tell.", "section": "Troubleshooting", "topic": "Linux", "page": "linux/performance/index.html", "anchor": "troubleshooting"}, {"cmd": "docker ps -a --format 'table {{.Names}}\\t{{.Status}}\\t{{.Ports}}'", "tip": "Readable custom columns — faster to scan than the default ps output.", "section": "Docker", "topic": "Docker", "page": "docker/index.html", "anchor": ""}, {"cmd": "docker exec -it mycontainer sh", "tip": "Get a shell in a running container — for poking around inside a live container.", "section": "Docker", "topic": "Docker", "page": "docker/index.html", "anchor": ""}, {"cmd": "docker run --rm -it --entrypoint sh myimage", "tip": "Inspect an image without running its default command — overrides the entrypoint just to look around.", "section": "Docker", "topic": "Docker", "page": "docker/index.html", "anchor": ""}, {"cmd": "docker stats --no-stream", "tip": "One-shot resource usage snapshot — --no-stream avoids the live-updating view when you just want a quick read.", "section": "Docker", "topic": "Docker", "page": "docker/index.html", "anchor": ""}, {"cmd": "docker system df", "tip": "Disk usage breakdown by images/containers/volumes — shows where Docker's actually spending disk space.", "section": "Docker", "topic": "Docker", "page": "docker/index.html", "anchor": ""}, {"cmd": "docker system prune -af --volumes", "tip": "Reclaim space — destructive, see Production Safety.", "section": "Docker", "topic": "Docker", "page": "docker/index.html", "anchor": ""}, {"cmd": "docker inspect --format '{{.State.Health.Status}}' mycontainer", "tip": "Pull one field instead of parsing full JSON — scriptable without needing jq.", "section": "Docker", "topic": "Docker", "page": "docker/index.html", "anchor": ""}, {"cmd": "docker build -t myimage:v1 .", "tip": "Build an image from a Dockerfile in the current directory — the standard local build step.", "section": "Docker", "topic": "Docker", "page": "docker/index.html", "anchor": ""}, {"cmd": "docker pull myimage:v1", "tip": "Download an image from a registry without running it — useful to pre-fetch before a deploy.", "section": "Docker", "topic": "Docker", "page": "docker/index.html", "anchor": ""}, {"cmd": "docker push myregistry/myimage:v1", "tip": "Upload an image to a registry — makes it available for others/other hosts to pull.", "section": "Docker", "topic": "Docker", "page": "docker/index.html", "anchor": ""}, {"cmd": "docker tag myimage:v1 myregistry/myimage:v1", "tip": "Add a new tag to an existing local image — registries often need a specific tag format before push.", "section": "Docker", "topic": "Docker", "page": "docker/index.html", "anchor": ""}, {"cmd": "docker rm mycontainer", "tip": "Remove a stopped container — frees the disk space it was holding.", "section": "Docker", "topic": "Docker", "page": "docker/index.html", "anchor": ""}, {"cmd": "docker rmi myimage:v1", "tip": "Remove a local image — frees disk space once nothing needs it anymore.", "section": "Docker", "topic": "Docker", "page": "docker/index.html", "anchor": ""}, {"cmd": "docker cp mycontainer:/app/log.txt ./log.txt", "tip": "Copy a file out of a container without exec-ing in — faster for a single file grab.", "section": "Docker", "topic": "Docker", "page": "docker/index.html", "anchor": ""}, {"cmd": "docker top mycontainer", "tip": "Processes running inside a container, from the host's view — like ps, but scoped to that container.", "section": "Docker", "topic": "Docker", "page": "docker/index.html", "anchor": ""}, {"cmd": "docker diff mycontainer", "tip": "Files changed vs the image's original filesystem — useful for spotting unexpected writes.", "section": "Docker", "topic": "Docker", "page": "docker/index.html", "anchor": ""}, {"cmd": "docker build --no-cache -t myimage:v1 .", "tip": "Force a full rebuild, ignoring cached layers — use when you suspect a stale cached layer is the problem.", "section": "Docker", "topic": "Docker", "page": "docker/index.html", "anchor": ""}, {"cmd": "docker history myimage:v1", "tip": "Every layer in an image, with size — find what's bloating it.", "section": "Docker", "topic": "Docker", "page": "docker/index.html", "anchor": ""}, {"cmd": "docker image prune -a", "tip": "Remove all unused images, not just dangling ones — more aggressive than a bare prune.", "section": "Docker", "topic": "Docker", "page": "docker/index.html", "anchor": ""}, {"cmd": "docker run --rm -it --user 0 myimage sh", "tip": "Drop in as root — overrides the image's default user, for debugging permissions.", "section": "Docker", "topic": "Docker", "page": "docker/index.html", "anchor": ""}, {"cmd": "docker logs --details mycontainer", "tip": "Include extra attributes in log output — labels etc., not just the line itself.", "section": "Docker", "topic": "Docker", "page": "docker/index.html", "anchor": ""}, {"cmd": "docker compose up -d", "tip": "Start everything in the background — the standard way to bring a stack up without blocking the terminal.", "section": "Docker Compose", "topic": "Docker", "page": "docker/index.html", "anchor": "docker-compose"}, {"cmd": "docker compose up -d --build", "tip": "Rebuild images first, then start — needed after a Dockerfile change, otherwise up reuses the old image.", "section": "Docker Compose", "topic": "Docker", "page": "docker/index.html", "anchor": "docker-compose"}, {"cmd": "docker compose down", "tip": "Stop and remove containers, networks — volumes are kept by default, add -v to also remove those.", "section": "Docker Compose", "topic": "Docker", "page": "docker/index.html", "anchor": "docker-compose"}, {"cmd": "docker compose down -v", "tip": "Also remove volumes — destructive, see Production Safety.", "section": "Docker Compose", "topic": "Docker", "page": "docker/index.html", "anchor": "docker-compose"}, {"cmd": "docker compose ps", "tip": "Status of every service in this project — confirms what's actually running vs defined.", "section": "Docker Compose", "topic": "Docker", "page": "docker/index.html", "anchor": "docker-compose"}, {"cmd": "docker compose logs -f service_name", "tip": "Follow logs for one service only — narrower than following the whole stack's combined logs.", "section": "Docker Compose", "topic": "Docker", "page": "docker/index.html", "anchor": "docker-compose"}, {"cmd": "docker compose exec service_name sh", "tip": "Shell into a running service — same idea as docker exec, scoped by compose service name.", "section": "Docker Compose", "topic": "Docker", "page": "docker/index.html", "anchor": "docker-compose"}, {"cmd": "docker compose restart service_name", "tip": "Restart one service without touching the rest — faster than a full compose down/up.", "section": "Docker Compose", "topic": "Docker", "page": "docker/index.html", "anchor": "docker-compose"}, {"cmd": "docker compose config", "tip": "Render the fully resolved config (env vars, overrides applied) — great for debugging &quot;why isn't my variable being picked up&quot;.", "section": "Docker Compose", "topic": "Docker", "page": "docker/index.html", "anchor": "docker-compose"}, {"cmd": "docker compose up -d --scale worker=3", "tip": "Run 3 instances of one service — a quick way to test load-balancing or scaling behavior locally.", "section": "Docker Compose", "topic": "Docker", "page": "docker/index.html", "anchor": "docker-compose"}, {"cmd": "docker compose -f docker-compose.yml -f docker-compose.override.yml up -d", "tip": "Explicitly combine multiple compose files — useful when override files aren't in the default auto-discovered location.", "section": "Docker Compose", "topic": "Docker", "page": "docker/index.html", "anchor": "docker-compose"}, {"cmd": "docker compose logs -f --tail=100 service_name", "tip": "Follow, but only the last 100 lines first — avoids a wall of scrollback on attach.", "section": "Docker Compose", "topic": "Docker", "page": "docker/index.html", "anchor": "docker-compose"}, {"cmd": "docker compose exec service_name env", "tip": "Check what env vars a service actually sees at runtime — confirms it matches what you think you set.", "section": "Docker Compose", "topic": "Docker", "page": "docker/index.html", "anchor": "docker-compose"}, {"cmd": "docker compose top", "tip": "Processes running inside each service's container — without exec-ing in first.", "section": "Docker Compose", "topic": "Docker", "page": "docker/index.html", "anchor": "docker-compose"}, {"cmd": "docker logs mycontainer", "tip": "Shows the actual error — works even on an already-stopped container.", "section": "Troubleshooting", "topic": "Docker", "page": "docker/index.html", "anchor": "troubleshooting"}, {"cmd": "docker inspect mycontainer --format '{{.State.ExitCode}}'", "tip": "Exit code — 137 usually means OOM-killed, 1 is a generic app error.", "section": "Troubleshooting", "topic": "Docker", "page": "docker/index.html", "anchor": "troubleshooting"}, {"cmd": "docker run -it --entrypoint sh myimage", "tip": "Override the entrypoint to get a shell instead — for inspecting an image that doesn't normally give you one.", "section": "Troubleshooting", "topic": "Docker", "page": "docker/index.html", "anchor": "troubleshooting"}, {"cmd": "docker system df", "tip": "Docker's own disk usage, separate from the host filesystem view — df on the host won't show this breakdown.", "section": "Troubleshooting", "topic": "Docker", "page": "docker/index.html", "anchor": "troubleshooting"}, {"cmd": "docker system prune -af --volumes", "tip": "Docker images/layers/volumes accumulate in their own storage driver — this is almost always the real cause.", "section": "Troubleshooting", "topic": "Docker", "page": "docker/index.html", "anchor": "troubleshooting"}, {"cmd": "docker network ls", "tip": "Confirm both containers are actually on the same network — the usual reason two containers can't reach each other.", "section": "Troubleshooting", "topic": "Docker", "page": "docker/index.html", "anchor": "troubleshooting"}, {"cmd": "docker network inspect &lt;network_name&gt;", "tip": "See which containers are attached, and their IPs — confirms network membership directly instead of guessing.", "section": "Troubleshooting", "topic": "Docker", "page": "docker/index.html", "anchor": "troubleshooting"}, {"cmd": "docker exec mycontainer1 ping mycontainer2", "tip": "Containers on the same user-defined network can reach each other by name — if this fails, they're not on the same network.", "section": "Troubleshooting", "topic": "Docker", "page": "docker/index.html", "anchor": "troubleshooting"}, {"cmd": "kubectl config get-contexts", "tip": "List every cluster/context you have configured — confirms which clusters kubectl even knows about.", "section": "Basic", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "basic"}, {"cmd": "kubectl config use-context mycontext", "tip": "Switch clusters — check this before anything destructive.", "section": "Basic", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "basic"}, {"cmd": "kubectl config set-context --current --namespace=myns", "tip": "Stop typing -n myns on every command — sets the default namespace for this context session.", "section": "Basic", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "basic"}, {"cmd": "kubectl get pods,svc,deploy -n myns", "tip": "Multiple resource types in one call — faster than three separate get commands.", "section": "Basic", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "basic"}, {"cmd": "kubectl apply -f manifest.yaml", "tip": "Create or update from a manifest — the standard way to apply any change declaratively.", "section": "Basic", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "basic"}, {"cmd": "kubectl delete -f manifest.yaml", "tip": "Remove everything defined in that manifest — cleaner than deleting resources one by one.", "section": "Basic", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "basic"}, {"cmd": "kubectl scale deployment/myapp --replicas=3", "tip": "Scale up/down manually — a quick override outside of an HPA or a manifest edit.", "section": "Basic", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "basic"}, {"cmd": "kubectl port-forward svc/myapp 8080:80", "tip": "Reach a cluster service from localhost — no ingress or public exposure needed just to poke at it.", "section": "Basic", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "basic"}, {"cmd": "kubectl cp mypod:/var/log/app.log ./app.log", "tip": "Copy a file out of a running pod — grab a log or config file without exec-ing in first.", "section": "Basic", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "basic"}, {"cmd": "kubectl get pods -o wide --sort-by=.status.startTime", "tip": "Newest pods last — quickly confirms a rollout actually replaced the old pods.", "section": "Basic", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "basic"}, {"cmd": "kubectl top pods --sort-by=memory", "tip": "Needs metrics-server installed, but invaluable for spotting a resource-hungry pod fast.", "section": "Basic", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "basic"}, {"cmd": "kubectl describe pod mypod", "tip": "Events at the bottom are usually the real answer — most people stop reading before they get there.", "section": "Basic", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "basic"}, {"cmd": "kubectl logs -f mypod --previous", "tip": "Logs from the container BEFORE the last crash — the one you actually need for CrashLoopBackOff.", "section": "Basic", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "basic"}, {"cmd": "kubectl get events --sort-by='.lastTimestamp' -A", "tip": "Cluster-wide event stream, chronological — catches things happening outside the namespace you were watching.", "section": "Basic", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "basic"}, {"cmd": "kubectl create namespace myns", "tip": "Creates a namespace — a logical partition for grouping related resources with its own RBAC boundary.", "section": "Basic", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "basic"}, {"cmd": "kubectl delete namespace myns", "tip": "Delete a namespace and everything in it — destructive.", "section": "Basic", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "basic"}, {"cmd": "kubectl get all -n myns", "tip": "Every common resource type in a namespace at once — a fast full picture instead of querying each type separately.", "section": "Basic", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "basic"}, {"cmd": "kubectl label pod mypod env=prod", "tip": "Attach a label to a running resource — labels are what selectors (Services, Deployments) actually match against.", "section": "Basic", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "basic"}, {"cmd": "kubectl annotate pod mypod note=&quot;value&quot;", "tip": "Attach metadata that isn't used for selection — good for notes/links, unlike labels which selectors match against.", "section": "Basic", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "basic"}, {"cmd": "kubectl get pod mypod -o yaml", "tip": "Full resource definition as YAML — includes server-set fields your original manifest never had.", "section": "Basic", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "basic"}, {"cmd": "kubectl edit deployment myapp", "tip": "Open a live resource in $EDITOR — applies immediately on save, no separate apply step.", "section": "Basic", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "basic"}, {"cmd": "kubectl set image deployment/myapp app=myapp:v2", "tip": "Update just the image of a container — no manifest edit needed for the most common single change.", "section": "Basic", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "basic"}, {"cmd": "kubectl rollout status deployment/myapp", "tip": "Watch a rollout until it completes or fails — blocks instead of you polling get pods repeatedly.", "section": "Basic", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "basic"}, {"cmd": "kubectl expose deployment myapp --port=80 --target-port=8080", "tip": "Quickly create a Service for an existing Deployment — skips writing a Service manifest by hand.", "section": "Basic", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "basic"}, {"cmd": "kubectl debug node/mynode -it --image=busybox", "tip": "Ephemeral debug pod on a node — no SSH access to the node itself required.", "section": "Basic", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "basic"}, {"cmd": "kubectl debug mypod -it --image=busybox --target=mypod", "tip": "Attach a debug container to a running pod — for images with no shell.", "section": "Basic", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "basic"}, {"cmd": "kubectl diff -f manifest.yaml", "tip": "See exactly what would change — catches a typo or unintended diff before it actually applies.", "section": "Basic", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "basic"}, {"cmd": "kubectl apply -f manifest.yaml --dry-run=server", "tip": "Server-side validation without applying — catches errors the API server would reject, without committing to them.", "section": "Basic", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "basic"}, {"cmd": "kubectl explain deployment.spec.strategy", "tip": "Built-in field docs, no browser needed — faster than searching the Kubernetes docs site mid-task.", "section": "Basic", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "basic"}, {"cmd": "kubectl rollout undo deployment/myapp", "tip": "Instant rollback to the previous revision — the fastest way to undo a bad deploy.", "section": "Basic", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "basic"}, {"cmd": "kubectl rollout history deployment/myapp", "tip": "See all revisions before deciding which to roll back to — rolling back blind can pick the wrong one.", "section": "Basic", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "basic"}, {"cmd": "oc rsh mypod", "tip": "OpenShift shorthand for exec -it ... sh — one less flag to remember on OpenShift specifically.", "section": "Basic", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "basic"}, {"cmd": "oc adm top pods --sort-by=cpu -n mynamespace", "tip": "OpenShift admin-level resource view — shows more than a regular user's view would.", "section": "Basic", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "basic"}, {"cmd": "kubectl get pods --field-selector=status.phase=Running -A", "tip": "Filter server-side instead of piping through grep — faster and doesn't rely on text matching a field name.", "section": "Basic", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "basic"}, {"cmd": "kubectl get pods -l app=myapp --show-labels", "tip": "Filter by label selector — --show-labels reveals every label, not just the one you filtered on.", "section": "Basic", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "basic"}, {"cmd": "kubectl exec -it mypod -c sidecar -- sh", "tip": "Target a specific container inside a multi-container pod — exec without -c hits the first container by default, which may be the wrong one.", "section": "Basic", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "basic"}, {"cmd": "kubectl cp mypod:/etc/config.yaml ./config.yaml -c sidecar", "tip": "Same idea as exec -c, but for copying files out of a specific container in a multi-container pod.", "section": "Basic", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "basic"}, {"cmd": "kubectl get pod mypod -o jsonpath='{.status.podIP}'", "tip": "Extract exactly one field, scriptable — no piping through jq needed for a simple lookup.", "section": "Basic", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "basic"}, {"cmd": "kubectl patch deployment myapp -p '{&quot;spec&quot;:{&quot;replicas&quot;:5}}'", "tip": "Imperative partial update — changes one field without needing a full manifest apply.", "section": "Basic", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "basic"}, {"cmd": "kubectl wait --for=condition=Ready pod/mypod --timeout=60s", "tip": "Block until a condition is met — useful in scripts/CI instead of polling in a loop yourself.", "section": "Basic", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "basic"}, {"cmd": "kubectl auth can-i delete pods -n myns", "tip": "Check your own RBAC permissions before you try and fail — confirms ahead of time instead of hitting a 403.", "section": "Basic", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "basic"}, {"cmd": "kubectl auth can-i delete pods --as=system:serviceaccount:myns:mysa", "tip": "Check what a specific service account can do — useful when debugging a pod's permission errors, not just your own.", "section": "Basic", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "basic"}, {"cmd": "kubectl describe pod mypod", "tip": "Events at the bottom almost always say why — insufficient CPU/memory, no matching node, unbound PVC.", "section": "Troubleshooting", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "troubleshooting"}, {"cmd": "kubectl get nodes -o wide", "tip": "Confirm there's actually capacity to schedule onto — a Pending pod is often just waiting on resources, not broken.", "section": "Troubleshooting", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "troubleshooting"}, {"cmd": "kubectl describe pod mypod | grep -A5 Events", "tip": "Wrong image tag, private registry auth missing, or a typo in the image name — the event message names which one.", "section": "Troubleshooting", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "troubleshooting"}, {"cmd": "kubectl get secret &lt;registry_secret&gt; -n mynamespace", "tip": "Confirm the pull secret exists in this namespace — secrets don't cross namespaces.", "section": "Troubleshooting", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "troubleshooting"}, {"cmd": "kubectl logs mypod --previous", "tip": "The crash reason is in the PREVIOUS container's logs — the new one just started and hasn't crashed yet.", "section": "Troubleshooting", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "troubleshooting"}, {"cmd": "kubectl describe pod mypod | grep -A3 &quot;Last State&quot;", "tip": "Exit code and reason without digging through full logs — the fast path when you just need the &quot;why&quot;, not the whole log.", "section": "Troubleshooting", "topic": "Kubernetes", "page": "kubernetes/index.html", "anchor": "troubleshooting"}, {"cmd": "helm repo add bitnami https://charts.bitnami.com/bitnami", "tip": "Add a chart repository — required before you can install anything from it.", "section": "Helm", "topic": "Kubernetes", "page": "kubernetes/helm/index.html", "anchor": ""}, {"cmd": "helm repo update", "tip": "Refresh the local index of available charts — without this, search/install can use stale versions.", "section": "Helm", "topic": "Kubernetes", "page": "kubernetes/helm/index.html", "anchor": ""}, {"cmd": "helm search repo &lt;name&gt;", "tip": "Find a chart across added repos — confirms the right chart name/version before installing.", "section": "Helm", "topic": "Kubernetes", "page": "kubernetes/helm/index.html", "anchor": ""}, {"cmd": "helm install &lt;release_name&gt; &lt;chart&gt; --set &lt;key&gt;=&lt;value&gt;", "tip": "Install, overriding one value inline — quick for a single change, use -f for anything more than a couple.", "section": "Helm", "topic": "Kubernetes", "page": "kubernetes/helm/index.html", "anchor": ""}, {"cmd": "helm upgrade &lt;release_name&gt; &lt;chart&gt; -f custom-values.yaml", "tip": "Upgrade using a full values file — more reproducible and reviewable than a long chain of --set flags.", "section": "Helm", "topic": "Kubernetes", "page": "kubernetes/helm/index.html", "anchor": ""}, {"cmd": "helm list -A", "tip": "Every release across every namespace — a full inventory instead of checking namespace by namespace.", "section": "Helm", "topic": "Kubernetes", "page": "kubernetes/helm/index.html", "anchor": ""}, {"cmd": "helm history &lt;release_name&gt;", "tip": "Revision history for a release — see every past upgrade before deciding what to roll back to.", "section": "Helm", "topic": "Kubernetes", "page": "kubernetes/helm/index.html", "anchor": ""}, {"cmd": "helm rollback &lt;release_name&gt; &lt;revision_number&gt;", "tip": "Roll back to a specific prior revision — undoes a bad upgrade using history from the command above.", "section": "Helm", "topic": "Kubernetes", "page": "kubernetes/helm/index.html", "anchor": ""}, {"cmd": "helm uninstall &lt;release_name&gt;", "tip": "Remove a release entirely — deletes the resources Helm created for it.", "section": "Helm", "topic": "Kubernetes", "page": "kubernetes/helm/index.html", "anchor": ""}, {"cmd": "helm show values &lt;chart&gt;", "tip": "Every configurable value a chart exposes, with its default — know what's actually overridable before writing a values file.", "section": "Helm", "topic": "Kubernetes", "page": "kubernetes/helm/index.html", "anchor": ""}, {"cmd": "helm show chart &lt;chart&gt;", "tip": "Chart metadata — version, description, dependencies.", "section": "Helm", "topic": "Kubernetes", "page": "kubernetes/helm/index.html", "anchor": ""}, {"cmd": "helm get manifest &lt;release_name&gt;", "tip": "The exact rendered YAML currently applied for a release — what's actually running, not just what the chart template says.", "section": "Helm", "topic": "Kubernetes", "page": "kubernetes/helm/index.html", "anchor": ""}, {"cmd": "helm dependency update &lt;chart&gt;", "tip": "Fetch/update a chart's subchart dependencies — required before install/upgrade if the chart declares any.", "section": "Helm", "topic": "Kubernetes", "page": "kubernetes/helm/index.html", "anchor": ""}, {"cmd": "helm upgrade --install &lt;release_name&gt; &lt;chart&gt; --atomic --timeout 5m", "tip": "Atomic upgrade: automatically rolls back if anything fails health checks — much safer than a bare upgrade for anything production-facing.", "section": "Helm", "topic": "Kubernetes", "page": "kubernetes/helm/index.html", "anchor": ""}, {"cmd": "helm template &lt;release_name&gt; &lt;chart&gt; -f values.yaml", "tip": "Render the final YAML locally, no cluster contact — see exactly what would be applied before it touches anything.", "section": "Helm", "topic": "Kubernetes", "page": "kubernetes/helm/index.html", "anchor": ""}, {"cmd": "helm lint &lt;chart&gt;", "tip": "Catch chart syntax/best-practice issues before packaging or installing — cheap to run, catches mistakes early.", "section": "Helm", "topic": "Kubernetes", "page": "kubernetes/helm/index.html", "anchor": ""}, {"cmd": "helm get values &lt;release_name&gt;", "tip": "See the actual values in effect for a release — not just your local file.", "section": "Helm", "topic": "Kubernetes", "page": "kubernetes/helm/index.html", "anchor": ""}, {"cmd": "helm diff upgrade &lt;release_name&gt; &lt;chart&gt; -f values.yaml", "tip": "(needs the helm-diff plugin) preview exactly what an upgrade would change — the Helm equivalent of kubectl diff.", "section": "Helm", "topic": "Kubernetes", "page": "kubernetes/helm/index.html", "anchor": ""}, {"cmd": "helm status myrelease", "tip": "Confirm a release is actually stuck, not just a slow upgrade still in progress.", "section": "Troubleshooting", "topic": "Kubernetes", "page": "kubernetes/helm/index.html", "anchor": "troubleshooting"}, {"cmd": "helm history myrelease", "tip": "Find the last known-good revision — the one to target with a rollback.", "section": "Troubleshooting", "topic": "Kubernetes", "page": "kubernetes/helm/index.html", "anchor": "troubleshooting"}, {"cmd": "kubectl delete secret -l owner=helm,name=myrelease,status=pending-upgrade -n mynamespace", "tip": "Helm's lock on a stuck release lives in a Secret — removing it (carefully) unblocks the next helm command.", "section": "Troubleshooting", "topic": "Kubernetes", "page": "kubernetes/helm/index.html", "anchor": "troubleshooting"}, {"cmd": "helm rollback myrelease", "tip": "If --atomic wasn't used, roll back manually — otherwise a failed upgrade could leave things half-applied.", "section": "Troubleshooting", "topic": "Kubernetes", "page": "kubernetes/helm/index.html", "anchor": "troubleshooting"}, {"cmd": "helm upgrade myrelease mychart --atomic --timeout 5m", "tip": "Use --atomic next time — auto-rollback instead of a half-applied upgrade.", "section": "Troubleshooting", "topic": "Kubernetes", "page": "kubernetes/helm/index.html", "anchor": "troubleshooting"}, {"cmd": "oc login https://api.cluster.example.com:6443 -u &lt;username&gt;", "tip": "Authenticates the CLI against a cluster's API server — required before any other oc command works.", "section": "OpenShift", "topic": "Kubernetes", "page": "kubernetes/openshift/index.html", "anchor": ""}, {"cmd": "oc whoami", "tip": "Confirm current user — useful after switching contexts/logins to avoid acting as the wrong account.", "section": "OpenShift", "topic": "Kubernetes", "page": "kubernetes/openshift/index.html", "anchor": ""}, {"cmd": "oc new-project &lt;project_name&gt;", "tip": "Create + switch to a new project — OpenShift's namespaced wrapper, adds quota/permissions on top of a plain namespace.", "section": "OpenShift", "topic": "Kubernetes", "page": "kubernetes/openshift/index.html", "anchor": ""}, {"cmd": "oc project &lt;project_name&gt;", "tip": "Switch between existing projects — changes which project subsequent commands target.", "section": "OpenShift", "topic": "Kubernetes", "page": "kubernetes/openshift/index.html", "anchor": ""}, {"cmd": "oc new-app --image=&lt;registry&gt;/&lt;image&gt;:&lt;tag&gt; --name=&lt;app_name&gt;", "tip": "Deploy straight from a container image — skips writing a manifest for a quick deployment.", "section": "OpenShift", "topic": "Kubernetes", "page": "kubernetes/openshift/index.html", "anchor": ""}, {"cmd": "oc create route edge &lt;route_name&gt; --service=&lt;service_name&gt; --port=&lt;port&gt; --hostname=&lt;hostname&gt;", "tip": "Expose a service with a TLS-terminated Route — OpenShift's built-in Ingress equivalent.", "section": "OpenShift", "topic": "Kubernetes", "page": "kubernetes/openshift/index.html", "anchor": ""}, {"cmd": "oc get routes", "tip": "List exposed routes and their hostnames — confirms what's actually externally reachable.", "section": "OpenShift", "topic": "Kubernetes", "page": "kubernetes/openshift/index.html", "anchor": ""}, {"cmd": "oc rsh mypod", "tip": "Shorthand for exec -it ... sh — one less flag to type on OpenShift specifically.", "section": "OpenShift", "topic": "Kubernetes", "page": "kubernetes/openshift/index.html", "anchor": ""}, {"cmd": "oc get projects", "tip": "Every project you can see, across the cluster — scoped to your own RBAC visibility.", "section": "OpenShift", "topic": "Kubernetes", "page": "kubernetes/openshift/index.html", "anchor": ""}, {"cmd": "oc delete project &lt;project_name&gt;", "tip": "Delete a project and everything in it — destructive.", "section": "OpenShift", "topic": "Kubernetes", "page": "kubernetes/openshift/index.html", "anchor": ""}, {"cmd": "oc status", "tip": "Quick visual summary of what's deployed in the current project — a fast overview without querying each resource type separately.", "section": "OpenShift", "topic": "Kubernetes", "page": "kubernetes/openshift/index.html", "anchor": ""}, {"cmd": "oc logs -f dc/myapp", "tip": "Follow logs for a DeploymentConfig — OpenShift's older pre-Deployment resource.", "section": "OpenShift", "topic": "Kubernetes", "page": "kubernetes/openshift/index.html", "anchor": ""}, {"cmd": "oc get build", "tip": "List builds — only relevant if using OpenShift's built-in S2I/BuildConfig pipeline.", "section": "OpenShift", "topic": "Kubernetes", "page": "kubernetes/openshift/index.html", "anchor": ""}, {"cmd": "oc start-build myapp", "tip": "Manually trigger a new build — rebuilds without waiting for the normal trigger (e.g. a git push)", "section": "OpenShift", "topic": "Kubernetes", "page": "kubernetes/openshift/index.html", "anchor": ""}, {"cmd": "oc adm policy add-scc-to-user anyuid -z &lt;service_account&gt; -n &lt;project&gt;", "tip": "Grant a Security Context Constraint to a service account — needed when a pod legitimately requires a UID the default restricted-v2 SCC blocks.", "section": "OpenShift", "topic": "Kubernetes", "page": "kubernetes/openshift/index.html", "anchor": ""}, {"cmd": "oc get scc", "tip": "List available SCCs and what each permits — check before requesting a broader one than actually needed.", "section": "OpenShift", "topic": "Kubernetes", "page": "kubernetes/openshift/index.html", "anchor": ""}, {"cmd": "oc adm cordon &lt;node_name&gt; &amp;&amp; oc adm drain &lt;node_name&gt; --ignore-daemonsets --delete-emptydir-data", "tip": "Safely empty a node before maintenance — cordon first so nothing new schedules there, then drain.", "section": "OpenShift", "topic": "Kubernetes", "page": "kubernetes/openshift/index.html", "anchor": ""}, {"cmd": "oc adm top nodes", "tip": "Node-level resource usage, cluster-wide — spot an overloaded node before pods start failing to schedule.", "section": "OpenShift", "topic": "Kubernetes", "page": "kubernetes/openshift/index.html", "anchor": ""}, {"cmd": "oc adm top pods --sort-by=cpu -n &lt;project&gt;", "tip": "Namespace-level pod resource usage — narrower than the cluster-wide view, scoped to one project.", "section": "OpenShift", "topic": "Kubernetes", "page": "kubernetes/openshift/index.html", "anchor": ""}, {"cmd": "oc adm upgrade", "tip": "Check current cluster version and available upgrade path — confirms what's actually running before assuming a feature exists.", "section": "OpenShift", "topic": "Kubernetes", "page": "kubernetes/openshift/index.html", "anchor": ""}, {"cmd": "oc get events --sort-by='.lastTimestamp' -n &lt;project&gt;", "tip": "Project-scoped event stream, chronological — same idea as kubectl get events -A, narrowed down.", "section": "OpenShift", "topic": "Kubernetes", "page": "kubernetes/openshift/index.html", "anchor": ""}, {"cmd": "oc get events -n myproject --sort-by='.lastTimestamp' | grep -i scc", "tip": "The denial reason is in the event — names the exact SCC rule that blocked it, not just &quot;denied&quot;.", "section": "Troubleshooting", "topic": "Kubernetes", "page": "kubernetes/openshift/index.html", "anchor": "troubleshooting"}, {"cmd": "oc get scc restricted-v2 -o yaml", "tip": "See exactly what the default SCC does and doesn't allow — confirms whether a broader SCC is actually needed.", "section": "Troubleshooting", "topic": "Kubernetes", "page": "kubernetes/openshift/index.html", "anchor": "troubleshooting"}, {"cmd": "oc get route myroute -o yaml", "tip": "Confirm the route actually points at the right service and port — a common source of &quot;route exists but doesn't work&quot;.", "section": "Troubleshooting", "topic": "Kubernetes", "page": "kubernetes/openshift/index.html", "anchor": "troubleshooting"}, {"cmd": "oc get endpoints myservice", "tip": "Empty endpoints means the service has no healthy pods behind it — the route is fine, the backend isn't.", "section": "Troubleshooting", "topic": "Kubernetes", "page": "kubernetes/openshift/index.html", "anchor": "troubleshooting"}, {"cmd": "argocd login &lt;argocd_host&gt; --username &lt;username&gt;", "tip": "Authenticate the CLI against an ArgoCD server — required before any other argocd command works.", "section": "ArgoCD", "topic": "Kubernetes", "page": "kubernetes/argocd/index.html", "anchor": ""}, {"cmd": "argocd app list", "tip": "Every application ArgoCD is managing, with sync/health status at a glance — a fleet-wide overview in one command.", "section": "ArgoCD", "topic": "Kubernetes", "page": "kubernetes/argocd/index.html", "anchor": ""}, {"cmd": "argocd app get &lt;app_name&gt;", "tip": "Detailed status for one app — sync state, health, resources.", "section": "ArgoCD", "topic": "Kubernetes", "page": "kubernetes/argocd/index.html", "anchor": ""}, {"cmd": "argocd app sync &lt;app_name&gt;", "tip": "Trigger a manual sync — pulls the latest from Git and applies it to the cluster right now, instead of waiting for auto-sync.", "section": "ArgoCD", "topic": "Kubernetes", "page": "kubernetes/argocd/index.html", "anchor": ""}, {"cmd": "argocd app diff &lt;app_name&gt;", "tip": "Preview the diff between Git and the live cluster — before syncing.", "section": "ArgoCD", "topic": "Kubernetes", "page": "kubernetes/argocd/index.html", "anchor": ""}, {"cmd": "argocd app history &lt;app_name&gt;", "tip": "Every past sync, with revision and timestamp — confirms exactly when and what was last deployed.", "section": "ArgoCD", "topic": "Kubernetes", "page": "kubernetes/argocd/index.html", "anchor": ""}, {"cmd": "argocd app rollback &lt;app_name&gt; &lt;history_id&gt;", "tip": "Roll back to a specific prior sync — undoes a bad deploy using the history above.", "section": "ArgoCD", "topic": "Kubernetes", "page": "kubernetes/argocd/index.html", "anchor": ""}, {"cmd": "argocd app delete &lt;app_name&gt;", "tip": "Remove an app from ArgoCD — has its own flag for deleting underlying resources too.", "section": "ArgoCD", "topic": "Kubernetes", "page": "kubernetes/argocd/index.html", "anchor": ""}, {"cmd": "argocd proj list", "tip": "ArgoCD projects — groupings that scope which repos/clusters/namespaces an app can use.", "section": "ArgoCD", "topic": "Kubernetes", "page": "kubernetes/argocd/index.html", "anchor": ""}, {"cmd": "argocd app logs &lt;app_name&gt; -f", "tip": "Stream an app's pod logs via the ArgoCD CLI — no kubectl context switch needed.", "section": "ArgoCD", "topic": "Kubernetes", "page": "kubernetes/argocd/index.html", "anchor": ""}, {"cmd": "argocd app sync &lt;app_name&gt; --prune", "tip": "Sync and also remove resources that were deleted from Git (off by default — a normal sync leaves orphaned resources alone)", "section": "ArgoCD", "topic": "Kubernetes", "page": "kubernetes/argocd/index.html", "anchor": ""}, {"cmd": "argocd app set &lt;app_name&gt; --sync-policy automated --auto-prune --self-heal", "tip": "Turn on full GitOps automation — auto-sync, prune, and auto-revert drift.", "section": "ArgoCD", "topic": "Kubernetes", "page": "kubernetes/argocd/index.html", "anchor": ""}, {"cmd": "argocd app wait &lt;app_name&gt; --health", "tip": "Block until an app reports healthy — useful in CI/CD pipelines after triggering a sync.", "section": "ArgoCD", "topic": "Kubernetes", "page": "kubernetes/argocd/index.html", "anchor": ""}, {"cmd": "argocd app resources &lt;app_name&gt;", "tip": "List every Kubernetes resource this app owns, with individual health — narrows a degraded app down to the specific resource.", "section": "ArgoCD", "topic": "Kubernetes", "page": "kubernetes/argocd/index.html", "anchor": ""}, {"cmd": "argocd repo list", "tip": "Git repositories ArgoCD is configured to pull from — confirms the actual source before assuming a sync issue.", "section": "ArgoCD", "topic": "Kubernetes", "page": "kubernetes/argocd/index.html", "anchor": ""}, {"cmd": "argocd cluster list", "tip": "Every cluster ArgoCD can deploy to — relevant if this instance manages more than just its own cluster.", "section": "ArgoCD", "topic": "Kubernetes", "page": "kubernetes/argocd/index.html", "anchor": ""}, {"cmd": "argocd app diff myapp", "tip": "See exactly what's different — sometimes it's a field a controller keeps overwriting (e.g. replica count under an HPA)", "section": "Troubleshooting", "topic": "Kubernetes", "page": "kubernetes/argocd/index.html", "anchor": "troubleshooting"}, {"cmd": "argocd app set myapp --sync-option ApplyOutOfSyncOnly=true", "tip": "Tell ArgoCD to leave a field alone — for fields that always drift against a controller.", "section": "Troubleshooting", "topic": "Kubernetes", "page": "kubernetes/argocd/index.html", "anchor": "troubleshooting"}, {"cmd": "argocd app resources myapp", "tip": "Health here means &quot;Kubernetes resources reached their expected state&quot; — it does NOT mean your application logic is working.", "section": "Troubleshooting", "topic": "Kubernetes", "page": "kubernetes/argocd/index.html", "anchor": "troubleshooting"}, {"cmd": "kubectl logs -f deployment/myapp -n mynamespace", "tip": "ArgoCD's health check passed the baton — actual app health is on you from here.", "section": "Troubleshooting", "topic": "Kubernetes", "page": "kubernetes/argocd/index.html", "anchor": "troubleshooting"}, {"cmd": "ansible-playbook site.yml", "tip": "Run a playbook against its default inventory — the standard way to apply it.", "section": "Ansible", "topic": "Ansible", "page": "ansible/index.html", "anchor": ""}, {"cmd": "ansible-playbook site.yml -i &lt;inventory_file&gt;", "tip": "Target a specific inventory — overrides the default, useful when managing multiple environments.", "section": "Ansible", "topic": "Ansible", "page": "ansible/index.html", "anchor": ""}, {"cmd": "ansible-playbook site.yml --limit &lt;host_or_group&gt;", "tip": "Run against a subset of hosts — narrows scope without editing the playbook or inventory.", "section": "Ansible", "topic": "Ansible", "page": "ansible/index.html", "anchor": ""}, {"cmd": "ansible-playbook site.yml --check", "tip": "Dry-run — shows what would change, changes nothing.", "section": "Ansible", "topic": "Ansible", "page": "ansible/index.html", "anchor": ""}, {"cmd": "ansible-playbook site.yml --check --diff", "tip": "Dry-run + shows the actual before/after diff per task — see exactly what would change before committing to it.", "section": "Ansible", "topic": "Ansible", "page": "ansible/index.html", "anchor": ""}, {"cmd": "ansible-playbook site.yml --tags &lt;tag_name&gt;", "tip": "Run only tasks with a given tag — skips the rest of a long playbook when you just need one part.", "section": "Ansible", "topic": "Ansible", "page": "ansible/index.html", "anchor": ""}, {"cmd": "ansible &lt;host_or_group&gt; -m ping", "tip": "Ad-hoc: confirm connectivity + Python interpreter — the fastest sanity check before trusting any playbook run against a host.", "section": "Ansible", "topic": "Ansible", "page": "ansible/index.html", "anchor": ""}, {"cmd": "ansible &lt;host_or_group&gt; -m shell -a &quot;&lt;command&gt;&quot;", "tip": "Ad-hoc: run one command on a group of hosts — no playbook needed for a quick one-off.", "section": "Ansible", "topic": "Ansible", "page": "ansible/index.html", "anchor": ""}, {"cmd": "ansible-inventory -i &lt;inventory_file&gt; --list", "tip": "See what Ansible thinks the inventory looks like — confirms hosts/groups resolved the way you expect.", "section": "Ansible", "topic": "Ansible", "page": "ansible/index.html", "anchor": ""}, {"cmd": "ansible-vault encrypt &lt;file.yml&gt;", "tip": "Encrypt a file containing secrets — safe to commit to git once encrypted.", "section": "Ansible", "topic": "Ansible", "page": "ansible/index.html", "anchor": ""}, {"cmd": "ansible-vault edit &lt;file.yml&gt;", "tip": "Edit an encrypted file in place — decrypts, opens your editor, re-encrypts on save automatically.", "section": "Ansible", "topic": "Ansible", "page": "ansible/index.html", "anchor": ""}, {"cmd": "ansible-vault view &lt;file.yml&gt;", "tip": "View without decrypting to disk — reads the content without leaving a plaintext copy behind.", "section": "Ansible", "topic": "Ansible", "page": "ansible/index.html", "anchor": ""}, {"cmd": "ansible-galaxy install -r requirements.yml", "tip": "Install roles/collections a project depends on — required before a playbook using them will actually run.", "section": "Ansible", "topic": "Ansible", "page": "ansible/index.html", "anchor": ""}, {"cmd": "ansible-doc -l", "tip": "List every module available locally — discover what's installed without searching docs online.", "section": "Ansible", "topic": "Ansible", "page": "ansible/index.html", "anchor": ""}, {"cmd": "ansible-doc &lt;module_name&gt;", "tip": "Full docs + examples for one module — offline, faster than searching online docs mid-task.", "section": "Ansible", "topic": "Ansible", "page": "ansible/index.html", "anchor": ""}, {"cmd": "ansible-config dump --only-changed", "tip": "See which config settings differ from Ansible's defaults — confirms what ansible.cfg is actually overriding.", "section": "Ansible", "topic": "Ansible", "page": "ansible/index.html", "anchor": ""}, {"cmd": "ansible-playbook site.yml --list-tasks", "tip": "Preview every task a playbook would run — a structural check before running anything for real.", "section": "Ansible", "topic": "Ansible", "page": "ansible/index.html", "anchor": ""}, {"cmd": "ansible-playbook site.yml --list-hosts", "tip": "Preview exactly which hosts a playbook would target — catches a wrong host pattern before it runs.", "section": "Ansible", "topic": "Ansible", "page": "ansible/index.html", "anchor": ""}, {"cmd": "ansible-playbook site.yml --syntax-check", "tip": "Catch YAML/syntax errors before touching any host — cheap to run, saves a failed run partway through.", "section": "Ansible", "topic": "Ansible", "page": "ansible/index.html", "anchor": ""}, {"cmd": "ansible-playbook site.yml --step", "tip": "Confirm each task interactively, one at a time — great for a risky playbook you don't fully trust yet.", "section": "Ansible", "topic": "Ansible", "page": "ansible/index.html", "anchor": ""}, {"cmd": "ansible-playbook site.yml -vvv", "tip": "Full verbosity, including the actual module arguments sent to each host — the real debugging tool when a task fails mysteriously.", "section": "Ansible", "topic": "Ansible", "page": "ansible/index.html", "anchor": ""}, {"cmd": "ansible-inventory -i &lt;inventory_file&gt; --graph", "tip": "Visualize group/host structure as a tree — much faster to read than the raw inventory YAML.", "section": "Ansible", "topic": "Ansible", "page": "ansible/index.html", "anchor": ""}, {"cmd": "ansible &lt;host_or_group&gt; -m setup -a &quot;filter=ansible_distribution*&quot;", "tip": "Pull just OS facts from a host — no full playbook run needed for a quick fact check.", "section": "Ansible", "topic": "Ansible", "page": "ansible/index.html", "anchor": ""}, {"cmd": "ansible-playbook site.yml --start-at-task=&quot;&lt;task_name&gt;&quot;", "tip": "Resume a long playbook from a specific task — avoids rerunning already-completed steps after a failure.", "section": "Ansible", "topic": "Ansible", "page": "ansible/index.html", "anchor": ""}, {"cmd": "ansible-playbook site.yml --diff --check -e &quot;myvar=value&quot;", "tip": "Dry-run with a variable override — no playbook/inventory edits needed.", "section": "Ansible", "topic": "Ansible", "page": "ansible/index.html", "anchor": ""}, {"cmd": "ansible all -m setup -a &quot;filter=ansible_default_ipv4&quot;", "tip": "Pull one fact across every host — fast, no full playbook run.", "section": "Ansible", "topic": "Ansible", "page": "ansible/index.html", "anchor": ""}, {"cmd": "ansible-vault rekey &lt;file.yml&gt;", "tip": "Change the encryption password on a vault-encrypted file — needed after a password rotation.", "section": "Ansible", "topic": "Ansible", "page": "ansible/index.html", "anchor": ""}, {"cmd": "ansible-playbook site.yml --vault-password-file ~/.vault_pass", "tip": "Supply the vault password from a file — needed for automation.", "section": "Ansible", "topic": "Ansible", "page": "ansible/index.html", "anchor": ""}, {"cmd": "ansible-playbook site.yml --limit &lt;failing_host&gt; -vvv", "tip": "Rerun against just that host with full verbosity — isolates the failure and shows exactly what Ansible did.", "section": "Troubleshooting", "topic": "Ansible", "page": "ansible/index.html", "anchor": "troubleshooting"}, {"cmd": "ansible &lt;failing_host&gt; -m setup | head -30", "tip": "Confirm facts gathering itself works — a surprising number of &quot;task&quot; failures are actually connection/facts problems.", "section": "Troubleshooting", "topic": "Ansible", "page": "ansible/index.html", "anchor": "troubleshooting"}, {"cmd": "ansible &lt;host&gt; -m ping -vvv", "tip": "Shows the exact SSH error — wrong key, wrong user, host key changed, etc.", "section": "Troubleshooting", "topic": "Ansible", "page": "ansible/index.html", "anchor": "troubleshooting"}, {"cmd": "ssh -vvv &lt;ansible_user&gt;@&lt;host&gt;", "tip": "Reproduce the connection manually — isolates SSH issues from Ansible itself.", "section": "Troubleshooting", "topic": "Ansible", "page": "ansible/index.html", "anchor": "troubleshooting"}, {"cmd": "export VAULT_ADDR=&quot;https://&lt;vault_host&gt;:8200&quot;", "tip": "Point the CLI at your Vault server — every other command needs this set first.", "section": "Vault", "topic": "Vault", "page": "vault/index.html", "anchor": ""}, {"cmd": "vault login", "tip": "Interactive login — the actual method depends on what auth backend is configured (token, LDAP, etc.)", "section": "Vault", "topic": "Vault", "page": "vault/index.html", "anchor": ""}, {"cmd": "vault status", "tip": "Is Vault up, sealed, and which node is active — nothing else works if it's sealed.", "section": "Vault", "topic": "Vault", "page": "vault/index.html", "anchor": ""}, {"cmd": "vault secrets list", "tip": "Every secrets engine mounted — confirms what's actually available before trying to read from it.", "section": "Vault", "topic": "Vault", "page": "vault/index.html", "anchor": ""}, {"cmd": "vault kv get secret/&lt;path&gt;", "tip": "Read a secret from a KV v2 engine — the everyday command for pulling a stored value.", "section": "Vault", "topic": "Vault", "page": "vault/index.html", "anchor": ""}, {"cmd": "vault kv get -field=&lt;key&gt; secret/&lt;path&gt;", "tip": "Pull just one field, scriptable — skips parsing the full JSON response for a single value.", "section": "Vault", "topic": "Vault", "page": "vault/index.html", "anchor": ""}, {"cmd": "vault kv put secret/&lt;path&gt; &lt;key&gt;=&lt;value&gt;", "tip": "Creates the secret if it doesn't exist, or adds a new version if it does — KV v2 keeps history either way.", "section": "Vault", "topic": "Vault", "page": "vault/index.html", "anchor": ""}, {"cmd": "vault kv list secret/&lt;path&gt;", "tip": "List keys under a path — discover what exists without reading (or having permission to read) the actual values.", "section": "Vault", "topic": "Vault", "page": "vault/index.html", "anchor": ""}, {"cmd": "vault token lookup", "tip": "Inspect your current token — policies, TTL, renewable.", "section": "Vault", "topic": "Vault", "page": "vault/index.html", "anchor": ""}, {"cmd": "vault policy list", "tip": "Every policy defined on this Vault — an inventory before checking what any one of them actually grants.", "section": "Vault", "topic": "Vault", "page": "vault/index.html", "anchor": ""}, {"cmd": "vault policy read &lt;policy_name&gt;", "tip": "See exactly what a policy allows — confirms access before assuming a permission denial is a bug.", "section": "Vault", "topic": "Vault", "page": "vault/index.html", "anchor": ""}, {"cmd": "vault kv delete secret/&lt;path&gt;", "tip": "Soft-delete the current version — KV v2 keeps history, so this is recoverable, not gone for good.", "section": "Vault", "topic": "Vault", "page": "vault/index.html", "anchor": ""}, {"cmd": "vault kv undelete -versions=&lt;n&gt; secret/&lt;path&gt;", "tip": "Recover a soft-deleted version — undoes the soft-delete above if it was a mistake.", "section": "Vault", "topic": "Vault", "page": "vault/index.html", "anchor": ""}, {"cmd": "vault kv metadata get secret/&lt;path&gt;", "tip": "Version history and metadata for a secret — see what changed and when, without needing read access to the values themselves.", "section": "Vault", "topic": "Vault", "page": "vault/index.html", "anchor": ""}, {"cmd": "vault auth list", "tip": "Every auth method enabled — confirms which ways exist to actually authenticate to this Vault.", "section": "Vault", "topic": "Vault", "page": "vault/index.html", "anchor": ""}, {"cmd": "vault list secret/", "tip": "List top-level paths in a KV mount — useful for discovering what exists.", "section": "Vault", "topic": "Vault", "page": "vault/index.html", "anchor": ""}, {"cmd": "vault lease revoke &lt;lease_id&gt;", "tip": "Manually revoke a dynamic secret's lease — cuts off access immediately instead of waiting for natural expiry.", "section": "Vault", "topic": "Vault", "page": "vault/index.html", "anchor": ""}, {"cmd": "vault kv get -format=json secret/&lt;path&gt; | jq '.data.data'", "tip": "Pull a secret as JSON and extract with jq — the practical way to use Vault output in scripts.", "section": "Vault", "topic": "Vault", "page": "vault/index.html", "anchor": ""}, {"cmd": "vault kv get -version=&lt;n&gt; secret/&lt;path&gt;", "tip": "KV v2 keeps history — read a previous version instead of the current one.", "section": "Vault", "topic": "Vault", "page": "vault/index.html", "anchor": ""}, {"cmd": "vault read database/creds/&lt;role_name&gt;", "tip": "Dynamic secret: get a short-lived DB credential — expires automatically, no static password to leak or rotate manually.", "section": "Vault", "topic": "Vault", "page": "vault/index.html", "anchor": ""}, {"cmd": "vault token renew", "tip": "Extend your current token's TTL — avoids losing access mid-task if the original TTL was too short.", "section": "Vault", "topic": "Vault", "page": "vault/index.html", "anchor": ""}, {"cmd": "vault audit list", "tip": "Confirm audit logging is actually enabled — worth checking once per environment, not assuming.", "section": "Vault", "topic": "Vault", "page": "vault/index.html", "anchor": ""}, {"cmd": "VAULT_TOKEN=&lt;token&gt; vault kv get secret/&lt;path&gt;", "tip": "Pass a token inline for a one-off command — careful, it hits shell history.", "section": "Vault", "topic": "Vault", "page": "vault/index.html", "anchor": ""}, {"cmd": "vault kv patch secret/&lt;path&gt; &lt;key&gt;=&lt;value&gt;", "tip": "Update just one field without overwriting the whole secret — KV v2 only, avoids clobbering fields you didn't mean to touch.", "section": "Vault", "topic": "Vault", "page": "vault/index.html", "anchor": ""}, {"cmd": "vault token create -policy=&lt;policy_name&gt; -ttl=1h", "tip": "Issue a short-lived scoped token — for automation, instead of sharing your own.", "section": "Vault", "topic": "Vault", "page": "vault/index.html", "anchor": ""}, {"cmd": "vault secrets tune -max-lease-ttl=8h secret/", "tip": "Cap how long dynamic secrets from this mount can live — tightens the default max lease, reduces exposure window.", "section": "Vault", "topic": "Vault", "page": "vault/index.html", "anchor": ""}, {"cmd": "vault operator init -key-shares=5 -key-threshold=3", "tip": "First-time init — generates unseal keys and the initial root token; store the keys somewhere that isn't this terminal's history.", "section": "Vault", "topic": "Vault", "page": "vault/index.html", "anchor": ""}, {"cmd": "vault operator unseal &lt;unseal_key&gt;", "tip": "Submit one unseal key — repeat key-threshold times after any restart.", "section": "Vault", "topic": "Vault", "page": "vault/index.html", "anchor": ""}, {"cmd": "vault secrets enable database", "tip": "Enable a secrets engine before it can be used — nothing under that path works until it's mounted.", "section": "Vault", "topic": "Vault", "page": "vault/index.html", "anchor": ""}, {"cmd": "vault policy write &lt;policy_name&gt; &lt;policy_file.hcl&gt;", "tip": "Apply an access policy from an HCL file — the standard way to define what a token/role can actually do.", "section": "Vault", "topic": "Vault", "page": "vault/index.html", "anchor": ""}, {"cmd": "vault status", "tip": "Confirms sealed state and how many unseal keys have been submitted — tells you exactly how far through unsealing you are.", "section": "Troubleshooting", "topic": "Vault", "page": "vault/index.html", "anchor": "troubleshooting"}, {"cmd": "vault operator unseal &lt;unseal_key&gt;", "tip": "Run key-threshold times total — by different key holders if properly distributed.", "section": "Troubleshooting", "topic": "Vault", "page": "vault/index.html", "anchor": "troubleshooting"}, {"cmd": "vault token lookup", "tip": "Check which policies are actually attached to your current token — confirms your real access before assuming a permission problem.", "section": "Troubleshooting", "topic": "Vault", "page": "vault/index.html", "anchor": "troubleshooting"}, {"cmd": "vault policy read &lt;policy_name&gt;", "tip": "Confirm the policy actually grants the path you're trying to read — a common gap is granting secret/data/x but not secret/metadata/x, which some operations also need.", "section": "Troubleshooting", "topic": "Vault", "page": "vault/index.html", "anchor": "troubleshooting"}, {"cmd": "sqlplus &lt;username&gt;/&lt;password&gt;@&lt;tns_alias&gt;", "tip": "Connect via a configured TNS entry — the standard way once tnsnames.ora is set up.", "section": "Oracle Database", "topic": "Oracle Database", "page": "oracle-db/index.html", "anchor": ""}, {"cmd": "sqlplus &lt;username&gt;/&lt;password&gt;@&lt;host&gt;:&lt;port&gt;/&lt;service_name&gt;", "tip": "Connect directly without relying on tnsnames.ora — useful on a box where it isn't configured.", "section": "Oracle Database", "topic": "Oracle Database", "page": "oracle-db/index.html", "anchor": ""}, {"cmd": "sqlplus / as sysdba", "tip": "Connect locally as SYSDBA — OS-level authentication, no password needed if you're the right OS user.", "section": "Oracle Database", "topic": "Oracle Database", "page": "oracle-db/index.html", "anchor": ""}, {"cmd": "tnsping &lt;tns_alias&gt;", "tip": "Confirm the listener is reachable — rules out network/listener issues before you start debugging the database itself.", "section": "Oracle Database", "topic": "Oracle Database", "page": "oracle-db/index.html", "anchor": ""}, {"cmd": "lsnrctl status", "tip": "Listener status — services registered, uptime.", "section": "Oracle Database", "topic": "Oracle Database", "page": "oracle-db/index.html", "anchor": ""}, {"cmd": "SELECT * FROM v$version;", "tip": "Confirm exact Oracle version/patch level — matters when a fix or feature is version-specific.", "section": "Oracle Database", "topic": "Oracle Database", "page": "oracle-db/index.html", "anchor": ""}, {"cmd": "SELECT user FROM dual;", "tip": "Current connected user — quick sanity check before you run anything against the wrong schema.", "section": "Oracle Database", "topic": "Oracle Database", "page": "oracle-db/index.html", "anchor": ""}, {"cmd": "SELECT table_name FROM user_tables ORDER BY table_name;", "tip": "Every table owned by the current user — a fast inventory before you go hunting through docs.", "section": "Oracle Database", "topic": "Oracle Database", "page": "oracle-db/index.html", "anchor": ""}, {"cmd": "DESC employees;", "tip": "Columns, types, nullability for one table — SQL*Plus shorthand for DESCRIBE, the first thing to check before writing a query against an unfamiliar table.", "section": "Oracle Database", "topic": "Oracle Database", "page": "oracle-db/index.html", "anchor": ""}, {"cmd": "SELECT username, status, sid, serial#\n  FROM   v$session;", "tip": "Who's connected right now — useful before a maintenance window to confirm nobody's mid-transaction.", "section": "Oracle Database", "topic": "Oracle Database", "page": "oracle-db/index.html", "anchor": ""}, {"cmd": "SELECT tablespace_name, ROUND(used_percent, 1) AS used_pct\n  FROM   dba_tablespace_usage_metrics;", "tip": "Quick tablespace usage check — Oracle tablespaces fill independently of OS disk space, so this catches a problem `df -h` never would.", "section": "Oracle Database", "topic": "Oracle Database", "page": "oracle-db/index.html", "anchor": ""}, {"cmd": "SELECT file_name, tablespace_name, bytes/1024/1024 AS size_mb\n  FROM   dba_data_files\n  WHERE  tablespace_name = '&lt;TABLESPACE&gt;';", "tip": "Datafiles backing a tablespace, and their sizes — shows exactly which physical files would need more room.", "section": "Oracle Database", "topic": "Oracle Database", "page": "oracle-db/index.html", "anchor": ""}, {"cmd": "SELECT name, open_mode, log_mode FROM v$database;", "tip": "Is it in ARCHIVELOG mode, mount/open state — confirms the DB is actually usable, not just that the process is running.", "section": "Oracle Database", "topic": "Oracle Database", "page": "oracle-db/index.html", "anchor": ""}, {"cmd": "ALTER SYSTEM SWITCH LOGFILE;", "tip": "Force a log switch — useful before checking archive status, so you're not waiting on a switch that hasn't happened yet.", "section": "Oracle Database", "topic": "Oracle Database", "page": "oracle-db/index.html", "anchor": ""}, {"cmd": "SELECT sid, serial#, sql_id, status, event\n  FROM   v$session\n  WHERE  status = 'ACTIVE';", "tip": "What's actually running right now, and what it's waiting on — the event column tells you if it's CPU-bound, I/O-bound, or blocked on a lock.", "section": "Oracle Database", "topic": "Oracle Database", "page": "oracle-db/index.html", "anchor": ""}, {"cmd": "ALTER SYSTEM KILL SESSION '&lt;sid&gt;,&lt;serial#&gt;';", "tip": "Kill a stuck/runaway session — confirm sid/serial# match the right one first, this is irreversible.", "section": "Oracle Database", "topic": "Oracle Database", "page": "oracle-db/index.html", "anchor": ""}, {"cmd": "SELECT sql_text, executions, elapsed_time/1000000 AS elapsed_sec\n  FROM   v$sql\n  ORDER  BY elapsed_time DESC\n  FETCH  FIRST 10 ROWS ONLY;", "tip": "Top time-consuming SQL, from the shared pool — the fastest way to find what's actually eating time, without guessing.", "section": "Oracle Database", "topic": "Oracle Database", "page": "oracle-db/index.html", "anchor": ""}, {"cmd": "SELECT blocking_session, sid, serial#, wait_class, seconds_in_wait\n  FROM   v$session\n  WHERE  blocking_session IS NOT NULL;", "tip": "Sessions currently blocked, and who's blocking them — the blocking_session column points straight at the root cause.", "section": "Oracle Database", "topic": "Oracle Database", "page": "oracle-db/index.html", "anchor": ""}, {"cmd": "EXPLAIN PLAN FOR SELECT * FROM employees WHERE department_id = 10;", "tip": "Generate an execution plan without running the query — safe to use on a slow query in production, since it never actually executes it.", "section": "Oracle Database", "topic": "Oracle Database", "page": "oracle-db/index.html", "anchor": ""}, {"cmd": "SELECT * FROM TABLE(DBMS_XPLAN.DISPLAY);", "tip": "Read the plan generated above — look for full table scans where an index was expected.", "section": "Oracle Database", "topic": "Oracle Database", "page": "oracle-db/index.html", "anchor": ""}, {"cmd": "SELECT index_name, table_name, uniqueness\n  FROM   user_indexes\n  WHERE  table_name = '&lt;TABLE_NAME&gt;';", "tip": "Indexes on a table, and whether they're actually unique as intended — a missing unique constraint is a common silent data-quality bug.", "section": "Oracle Database", "topic": "Oracle Database", "page": "oracle-db/index.html", "anchor": ""}, {"cmd": "SELECT name, value, description\n  FROM   v$parameter\n  WHERE  name LIKE '%&lt;parameter_fragment&gt;%';", "tip": "Check the live value of an init parameter — reading doesn't need a restart, only some changes do.", "section": "Oracle Database", "topic": "Oracle Database", "page": "oracle-db/index.html", "anchor": ""}, {"cmd": "SELECT * FROM v$diag_info WHERE name = 'Diag Trace';", "tip": "Where the alert log / trace files actually live on disk — the path varies by version/config, don't assume it.", "section": "Oracle Database", "topic": "Oracle Database", "page": "oracle-db/index.html", "anchor": ""}, {"cmd": "SELECT owner, object_name, object_type", "tip": "Every invalid object in the schema — stale views/procedures after a migration.", "section": "Oracle Database", "topic": "Oracle Database", "page": "oracle-db/index.html", "anchor": ""}, {"cmd": "SELECT profile, resource_name, limit", "tip": "Password/resource limits applied to a user's profile — check before assuming a lockout is a mistake.", "section": "Oracle Database", "topic": "Oracle Database", "page": "oracle-db/index.html", "anchor": ""}, {"cmd": "SELECT username, account_status, lock_date", "tip": "Confirm whether an account is actually locked, and since when — separates a real lockout from a forgotten password.", "section": "Oracle Database", "topic": "Oracle Database", "page": "oracle-db/index.html", "anchor": ""}, {"cmd": "expdp &lt;username&gt;/&lt;password&gt;@&lt;tns_alias&gt; directory=DATA_PUMP_DIR dumpfile=full_%U.dmp logfile=export.log full=y", "tip": "Full database export — %U auto-splits into multiple numbered files.", "section": "Backup &amp; restore (Data Pump)", "topic": "Oracle Database", "page": "oracle-db/index.html", "anchor": "backup-restore-data-pump"}, {"cmd": "expdp &lt;username&gt;/&lt;password&gt;@&lt;tns_alias&gt; schemas=&lt;SCHEMA_NAME&gt; directory=DATA_PUMP_DIR dumpfile=schema.dmp logfile=export_schema.log", "tip": "Export just one schema — the most common case in practice, smaller and faster than a full export.", "section": "Backup &amp; restore (Data Pump)", "topic": "Oracle Database", "page": "oracle-db/index.html", "anchor": "backup-restore-data-pump"}, {"cmd": "expdp &lt;username&gt;/&lt;password&gt;@&lt;tns_alias&gt; tables=&lt;SCHEMA_NAME&gt;.&lt;TABLE_NAME&gt; directory=DATA_PUMP_DIR dumpfile=table.dmp", "tip": "Export a single table — a quick safety net before a risky migration touching just that table.", "section": "Backup &amp; restore (Data Pump)", "topic": "Oracle Database", "page": "oracle-db/index.html", "anchor": "backup-restore-data-pump"}, {"cmd": "expdp &lt;username&gt;/&lt;password&gt;@&lt;tns_alias&gt; parfile=export.par", "tip": "Everything above as a parameter file instead of a long command line — the real-world way this is actually run.", "section": "Backup &amp; restore (Data Pump)", "topic": "Oracle Database", "page": "oracle-db/index.html", "anchor": "backup-restore-data-pump"}, {"cmd": "impdp &lt;username&gt;/&lt;password&gt;@&lt;tns_alias&gt; directory=DATA_PUMP_DIR dumpfile=schema.dmp logfile=import.log", "tip": "Import a Data Pump dump — needs the same directory object that was used for the export.", "section": "Backup &amp; restore (Data Pump)", "topic": "Oracle Database", "page": "oracle-db/index.html", "anchor": "backup-restore-data-pump"}, {"cmd": "impdp &lt;username&gt;/&lt;password&gt;@&lt;tns_alias&gt; parfile=import.par remap_schema=&lt;OLD_SCHEMA&gt;:&lt;NEW_SCHEMA&gt;", "tip": "Import into a differently-named schema — common when restoring into a test/staging environment.", "section": "Backup &amp; restore (Data Pump)", "topic": "Oracle Database", "page": "oracle-db/index.html", "anchor": "backup-restore-data-pump"}, {"cmd": "impdp &lt;username&gt;/&lt;password&gt;@&lt;tns_alias&gt; directory=DATA_PUMP_DIR dumpfile=schema.dmp sqlfile=preview.sql", "tip": "Don't actually import — just generate the DDL it WOULD run, to review first.", "section": "Backup &amp; restore (Data Pump)", "topic": "Oracle Database", "page": "oracle-db/index.html", "anchor": "backup-restore-data-pump"}, {"cmd": "SELECT directory_name, directory_path FROM dba_directories;", "tip": "Confirm the DIRECTORY object exists and points where expected — before expdp fails on it.", "section": "Backup &amp; restore (Data Pump)", "topic": "Oracle Database", "page": "oracle-db/index.html", "anchor": "backup-restore-data-pump"}, {"cmd": "rman target /", "tip": "Connect to the target database — opens an RMAN session for backup/restore operations.", "section": "Backup &amp; restore (Data Pump)", "topic": "Oracle Database", "page": "oracle-db/index.html", "anchor": "backup-restore-data-pump"}, {"cmd": "rman target / &lt;&lt;&lt; &quot;BACKUP DATABASE PLUS ARCHIVELOG;&quot;", "tip": "Full backup — includes the archived logs needed to make the backup consistent and restorable.", "section": "Backup &amp; restore (Data Pump)", "topic": "Oracle Database", "page": "oracle-db/index.html", "anchor": "backup-restore-data-pump"}, {"cmd": "rman target / &lt;&lt;&lt; &quot;BACKUP DATABASE PLUS ARCHIVELOG DELETE INPUT;&quot;", "tip": "Same, and delete archive logs once safely backed up — prevents them piling up.", "section": "Backup &amp; restore (Data Pump)", "topic": "Oracle Database", "page": "oracle-db/index.html", "anchor": "backup-restore-data-pump"}, {"cmd": "rman target / &lt;&lt;&lt; &quot;LIST BACKUP SUMMARY;&quot;", "tip": "See what backups actually exist and when they ran — confirm a backup job actually succeeded, don't just assume it did.", "section": "Backup &amp; restore (Data Pump)", "topic": "Oracle Database", "page": "oracle-db/index.html", "anchor": "backup-restore-data-pump"}, {"cmd": "rman target / &lt;&lt;&lt; &quot;RESTORE DATABASE VALIDATE;&quot;", "tip": "Dry-run a restore without touching anything — confirms the backup is actually usable, before you're in an emergency and find out it isn't.", "section": "Backup &amp; restore (Data Pump)", "topic": "Oracle Database", "page": "oracle-db/index.html", "anchor": "backup-restore-data-pump"}, {"cmd": "lsnrctl status", "tip": "Is the listener even up — the first thing to check, since no listener means no connections regardless of the DB's own state.", "section": "Troubleshooting", "topic": "Oracle Database", "page": "oracle-db/index.html", "anchor": "troubleshooting"}, {"cmd": "sqlplus / as sysdba &lt;&lt;&lt; &quot;SELECT status FROM v\\$instance;&quot;", "tip": "Is the instance actually open, or stuck in MOUNT — a DB can be &quot;running&quot; but not actually accepting application connections.", "section": "Troubleshooting", "topic": "Oracle Database", "page": "oracle-db/index.html", "anchor": "troubleshooting"}, {"cmd": "SELECT * FROM v$flash_recovery_area_usage;", "tip": "Almost always the recovery area filling up — check this before digging into anything more exotic.", "section": "Troubleshooting", "topic": "Oracle Database", "page": "oracle-db/index.html", "anchor": "troubleshooting"}, {"cmd": "rman target / &lt;&lt;&lt; &quot;DELETE ARCHIVELOG ALL COMPLETED BEFORE 'SYSDATE-3';&quot;", "tip": "Clear old archived logs older than 3 days — adjust the window to your actual recovery needs before running.", "section": "Troubleshooting", "topic": "Oracle Database", "page": "oracle-db/index.html", "anchor": "troubleshooting"}, {"cmd": "SELECT tablespace_name, ROUND(used_percent, 1)\n  FROM   dba_tablespace_usage_metrics\n  WHERE  used_percent &gt; 90;", "tip": "Confirm which tablespace first — don't guess and extend the wrong one.", "section": "Troubleshooting", "topic": "Oracle Database", "page": "oracle-db/index.html", "anchor": "troubleshooting"}, {"cmd": "ALTER TABLESPACE mytablespace ADD DATAFILE '/path/to/new_datafile.dbf' SIZE 500M AUTOEXTEND ON;", "tip": "Add space to the tablespace — autoextend prevents this exact problem from recurring immediately.", "section": "Troubleshooting", "topic": "Oracle Database", "page": "oracle-db/index.html", "anchor": "troubleshooting"}, {"cmd": "psql -h &lt;host&gt; -U &lt;username&gt; -d &lt;database&gt;", "tip": "Opens an interactive session against a database — the standard way to poke around manually.", "section": "PostgreSQL", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": ""}, {"cmd": "psql -h &lt;host&gt; -U &lt;username&gt; -d &lt;database&gt; -c &quot;&lt;SQL&gt;&quot;", "tip": "Run one statement without an interactive session — scriptable, no psql prompt needed.", "section": "PostgreSQL", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": ""}, {"cmd": "pg_dump -h &lt;host&gt; -U &lt;username&gt; &lt;database&gt; &gt; backup.sql", "tip": "Logical backup, plain SQL — human-readable, restorable with just psql -f, no special tooling.", "section": "PostgreSQL", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": ""}, {"cmd": "pg_dump -Fc -h &lt;host&gt; -U &lt;username&gt; &lt;database&gt; &gt; backup.dump", "tip": "Custom format — required for pg_restore, supports parallel restore.", "section": "PostgreSQL", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": ""}, {"cmd": "pg_restore -h &lt;host&gt; -U &lt;username&gt; -d &lt;database&gt; backup.dump", "tip": "Restore from a custom-format dump — needs pg_restore specifically, plain SQL won't work here.", "section": "PostgreSQL", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": ""}, {"cmd": "\\l", "tip": "List databases — the first thing to check when you're not sure which database you're even connected to.", "section": "PostgreSQL", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": ""}, {"cmd": "\\c &lt;database&gt;", "tip": "Switch database — psql sessions are locked to one database, this is how you move to another.", "section": "PostgreSQL", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": ""}, {"cmd": "\\dt", "tip": "List tables in the current schema — a fast inventory before writing a query against an unfamiliar database.", "section": "PostgreSQL", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": ""}, {"cmd": "\\d &lt;table&gt;", "tip": "Describe a table: columns, types, indexes, constraints — the first thing to check before writing a query against it.", "section": "PostgreSQL", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": ""}, {"cmd": "\\du", "tip": "List roles/users and their privileges — confirms who can actually do what, not just who exists.", "section": "PostgreSQL", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": ""}, {"cmd": "\\dx", "tip": "List installed extensions — confirms whether something like pg_stat_statements is even available before you try to query it.", "section": "PostgreSQL", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": ""}, {"cmd": "SELECT version();", "tip": "Confirm exact PostgreSQL version — matters since syntax and available features differ across major versions.", "section": "PostgreSQL", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": ""}, {"cmd": "SELECT current_user, current_database();", "tip": "Who you're connected as, and to which database — a quick sanity check before running anything destructive.", "section": "PostgreSQL", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": ""}, {"cmd": "SELECT * FROM pg_stat_activity WHERE state = 'active';", "tip": "What's running right now — the starting point for almost any performance investigation.", "section": "PostgreSQL", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": ""}, {"cmd": "SELECT pg_size_pretty(pg_database_size('&lt;database&gt;'));", "tip": "Database size, human-readable — quick check before assuming disk pressure is unrelated to this database.", "section": "PostgreSQL", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": ""}, {"cmd": "SELECT relname, pg_size_pretty(pg_total_relation_size(relid))\n  FROM   pg_catalog.pg_statio_user_tables\n  ORDER  BY pg_total_relation_size(relid) DESC\n  LIMIT  10;", "tip": "Largest tables in the current database — usually the first suspects when disk usage grows unexpectedly.", "section": "PostgreSQL", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": ""}, {"cmd": "SELECT pid, now() - query_start AS duration, query\n  FROM   pg_stat_activity\n  WHERE  state = 'active'\n  ORDER  BY duration DESC;", "tip": "Longest-running active queries, sorted — the fastest way to spot a query that's stuck or badly optimized.", "section": "PostgreSQL", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": ""}, {"cmd": "SELECT pg_terminate_backend(&lt;pid&gt;);", "tip": "Kill a stuck query by PID — confirm it's the right one via the query above first, this is irreversible.", "section": "PostgreSQL", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": ""}, {"cmd": "EXPLAIN ANALYZE &lt;query&gt;;", "tip": "Actual execution plan + real timings — the planner's estimate can be wildly wrong, this runs the query and shows what actually happened.", "section": "PostgreSQL", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": ""}, {"cmd": "VACUUM (VERBOSE, ANALYZE) &lt;table&gt;;", "tip": "Reclaim dead tuple space and refresh planner stats — routine maintenance, not just an emergency tool.", "section": "PostgreSQL", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": ""}, {"cmd": "SELECT client_addr, state, sent_lsn, replay_lsn,\n       pg_wal_lsn_diff(sent_lsn, replay_lsn) AS lag_bytes\n  FROM   pg_stat_replication;", "tip": "Replication lag, if this instance has standbys — confirms replicas are actually keeping up, not just connected.", "section": "PostgreSQL", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": ""}, {"cmd": "SELECT schemaname, relname, n_dead_tup, n_live_tup\n  FROM   pg_stat_user_tables\n  ORDER  BY n_dead_tup DESC\n  LIMIT  10;", "tip": "Dead-tuple bloat per table — the number autovacuum is racing against.", "section": "PostgreSQL", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": ""}, {"cmd": "SELECT indexrelname, idx_scan, idx_tup_read\n  FROM   pg_stat_user_indexes\n  WHERE  idx_scan &lt; 50\n  ORDER  BY idx_scan;", "tip": "Indexes that are barely (or never) used — candidates for dropping.", "section": "PostgreSQL", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": ""}, {"cmd": "SELECT locktype, relation::regclass, mode, granted, pid\n  FROM   pg_locks\n  WHERE  NOT granted;", "tip": "Current locks — granted=false rows are the ones actually blocked.", "section": "PostgreSQL", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": ""}, {"cmd": "SELECT query, calls, total_exec_time, mean_exec_time\n  FROM   pg_stat_statements\n  ORDER  BY total_exec_time DESC\n  LIMIT  10;", "tip": "Top queries by total time — needs the pg_stat_statements extension enabled, the standard way to find what's actually slow across the whole workload.", "section": "PostgreSQL", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": ""}, {"cmd": "SELECT rolname, rolsuper, rolcanlogin", "tip": "Roles/users and whether they're superusers or can even log in — a quick security-relevant inventory.", "section": "PostgreSQL", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": ""}, {"cmd": "SELECT n.nspname AS schema, c.relname AS table, c.reltuples::bigint AS approx_rows\n  FROM   pg_class c\n  JOIN   pg_namespace n ON n.oid = c.relnamespace\n  WHERE  c.relkind = 'r'\n  ORDER  BY c.reltuples DESC\n  LIMIT  10;", "tip": "Approximate row counts for every table — fast because it skips a full COUNT scan, good enough for a quick size sense.", "section": "PostgreSQL", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": ""}, {"cmd": "SELECT datname, numbackends, xact_commit, xact_rollback", "tip": "Per-database activity summary — commit/rollback ratio hints at app-level error rates.", "section": "PostgreSQL", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": ""}, {"cmd": "pg_dump -h &lt;host&gt; -U &lt;username&gt; -d &lt;database&gt; -Fp &gt; backup.sql", "tip": "Plain SQL, human-readable — restore with psql -f, no special tooling needed.", "section": "Backup &amp; restore", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": "backup-restore"}, {"cmd": "pg_dump -h &lt;host&gt; -U &lt;username&gt; -d &lt;database&gt; -Fc -f backup.dump", "tip": "Custom format — compressed, required for pg_restore, supports selective/parallel restore.", "section": "Backup &amp; restore", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": "backup-restore"}, {"cmd": "pg_dump -h &lt;host&gt; -U &lt;username&gt; -d &lt;database&gt; -Fd -j 4 -f backup_dir", "tip": "Directory format, dumped in parallel with 4 jobs — much faster on a large database.", "section": "Backup &amp; restore", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": "backup-restore"}, {"cmd": "pg_dumpall -h &lt;host&gt; -U &lt;username&gt; &gt; full_cluster.sql", "tip": "Every database in the cluster, plus roles/tablespaces — pg_dump alone only covers one database.", "section": "Backup &amp; restore", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": "backup-restore"}, {"cmd": "pg_dump --schema-only -h &lt;host&gt; -U &lt;username&gt; -d &lt;database&gt; &gt; schema.sql", "tip": "Structure only, no data — useful for spinning up an empty copy of the schema.", "section": "Backup &amp; restore", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": "backup-restore"}, {"cmd": "pg_dump --data-only -h &lt;host&gt; -U &lt;username&gt; -d &lt;database&gt; &gt; data.sql", "tip": "Data only, no structure — for reloading into an already-migrated schema.", "section": "Backup &amp; restore", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": "backup-restore"}, {"cmd": "pg_dump -t &lt;schema&gt;.&lt;table&gt; -h &lt;host&gt; -U &lt;username&gt; -d &lt;database&gt; &gt; table.sql", "tip": "A single table, not the whole database — useful before a risky change touching just that table.", "section": "Backup &amp; restore", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": "backup-restore"}, {"cmd": "psql -h &lt;host&gt; -U &lt;username&gt; -d &lt;database&gt; -f backup.sql", "tip": "Restore a plain-SQL dump — just runs the SQL file through psql.", "section": "Backup &amp; restore", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": "backup-restore"}, {"cmd": "pg_restore -h &lt;host&gt; -U &lt;username&gt; -d &lt;database&gt; backup.dump", "tip": "Restore a custom-format dump — needs pg_restore specifically, this format isn't plain SQL.", "section": "Backup &amp; restore", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": "backup-restore"}, {"cmd": "pg_restore -h &lt;host&gt; -U &lt;username&gt; -d &lt;database&gt; -j 4 backup_dir", "tip": "Parallel restore from directory format — matches the parallel dump above.", "section": "Backup &amp; restore", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": "backup-restore"}, {"cmd": "pg_restore -l backup.dump", "tip": "List the contents of a dump without restoring anything — confirm what's actually in it first.", "section": "Backup &amp; restore", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": "backup-restore"}, {"cmd": "pg_restore -h &lt;host&gt; -U &lt;username&gt; -d &lt;database&gt; -t &lt;table&gt; backup.dump", "tip": "Restore just one table out of a full dump — no need to restore everything to get one table back.", "section": "Backup &amp; restore", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": "backup-restore"}, {"cmd": "pg_basebackup -h &lt;host&gt; -U &lt;username&gt; -D /backup/path -Fp -Xs -P", "tip": "Full physical copy of the data directory, streaming WAL as it goes — the basis for point-in-time recovery, not just a snapshot.", "section": "Backup &amp; restore", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": "backup-restore"}, {"cmd": "pg_basebackup -h &lt;host&gt; -U &lt;username&gt; -D /backup/path -Ft -z -P", "tip": "Same idea, but tarred and gzip-compressed output — smaller for storage/transfer than a plain directory.", "section": "Backup &amp; restore", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": "backup-restore"}, {"cmd": "SELECT count(*), state\n  FROM   pg_stat_activity\n  GROUP  BY state;", "tip": "See where connections are actually going — active vs idle, before assuming the count itself is the problem.", "section": "Troubleshooting", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": "troubleshooting"}, {"cmd": "SELECT pid, state, now() - state_change AS idle_for\n  FROM   pg_stat_activity\n  WHERE  state = 'idle'\n  ORDER  BY idle_for DESC\n  LIMIT  10;", "tip": "Long-idle connections usually mean pool misconfiguration — real active load looks different in this same view.", "section": "Troubleshooting", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": "troubleshooting"}, {"cmd": "SELECT client_addr, pg_wal_lsn_diff(sent_lsn, replay_lsn) AS lag_bytes\n  FROM   pg_stat_replication;", "tip": "Confirm lag is actually growing over successive checks — a momentary nonzero value alone isn't necessarily a problem.", "section": "Troubleshooting", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": "troubleshooting"}, {"cmd": "SELECT pid, query, state, wait_event_type\n  FROM   pg_stat_activity\n  WHERE  wait_event_type = 'Lock';", "tip": "Who's waiting, and on what kind of lock — narrows a stuck query down to a specific blocking cause.", "section": "Troubleshooting", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": "troubleshooting"}, {"cmd": "SELECT pg_terminate_backend(&lt;pid&gt;);", "tip": "Terminate the blocking session once you've confirmed which one it is — this is irreversible, don't guess.", "section": "Troubleshooting", "topic": "PostgreSQL", "page": "postgresql/index.html", "anchor": "troubleshooting"}, {"cmd": "java weblogic.WLST", "tip": "Start WLST interactively — a Jython shell for exploring and managing the domain live.", "section": "WebLogic", "topic": "WebLogic", "page": "weblogic/index.html", "anchor": ""}, {"cmd": "java weblogic.WLST &lt;script.py&gt;", "tip": "Run a WLST script non-interactively — the way to automate repeatable admin tasks instead of typing them each time.", "section": "WebLogic", "topic": "WebLogic", "page": "weblogic/index.html", "anchor": ""}, {"cmd": "$DOMAIN_HOME/bin/startWebLogic.sh", "tip": "Start the admin server in the foreground — first-boot errors print directly instead of hiding in a log you have to go find.", "section": "WebLogic", "topic": "WebLogic", "page": "weblogic/index.html", "anchor": ""}, {"cmd": "$DOMAIN_HOME/bin/startManagedWebLogic.sh &lt;server_name&gt; &lt;admin_url&gt;", "tip": "Start a managed server, pointing at the admin server — needed for it to register and pull its config.", "section": "WebLogic", "topic": "WebLogic", "page": "weblogic/index.html", "anchor": ""}, {"cmd": "nmConnect() / nmStart('&lt;server_name&gt;')", "tip": "Start a server via Node Manager instead of the shell script — Node Manager can restart it automatically if it crashes, a plain script start can't.", "section": "WebLogic", "topic": "WebLogic", "page": "weblogic/index.html", "anchor": ""}, {"cmd": "connect('&lt;username&gt;', '&lt;password&gt;', 't3://&lt;host&gt;:&lt;port&gt;')", "tip": "Connect to a running admin server — required before any other WLST command against a live domain works.", "section": "WebLogic", "topic": "WebLogic", "page": "weblogic/index.html", "anchor": ""}, {"cmd": "domainRuntime()", "tip": "Switch to the domain runtime MBean tree — live runtime state, as opposed to static persisted config.", "section": "WebLogic", "topic": "WebLogic", "page": "weblogic/index.html", "anchor": ""}, {"cmd": "cd('/ServerRuntimes/&lt;server_name&gt;/JMSRuntime')", "tip": "Navigate the MBean tree like a filesystem — cd/ls work the same way you'd expect from a shell.", "section": "WebLogic", "topic": "WebLogic", "page": "weblogic/index.html", "anchor": ""}, {"cmd": "state('&lt;server_name&gt;')", "tip": "RUNNING / ADMIN / FAILED etc — the actual state of one managed server, not just whether its process exists.", "section": "WebLogic", "topic": "WebLogic", "page": "weblogic/index.html", "anchor": ""}, {"cmd": "ls()", "tip": "List MBeans/attributes at the current tree location — discover what's available without external docs.", "section": "WebLogic", "topic": "WebLogic", "page": "weblogic/index.html", "anchor": ""}, {"cmd": "serverConfig()", "tip": "Switch to the domain config MBean tree — persisted config, not live state.", "section": "WebLogic", "topic": "WebLogic", "page": "weblogic/index.html", "anchor": ""}, {"cmd": "cd('/Servers/&lt;server_name&gt;')", "tip": "Navigate the config tree for one managed server's static configuration — persisted settings, not the live runtime view.", "section": "WebLogic", "topic": "WebLogic", "page": "weblogic/index.html", "anchor": ""}, {"cmd": "cmo.getListenPort()", "tip": "Read one attribute off the current MBean — cmo = current management object.", "section": "WebLogic", "topic": "WebLogic", "page": "weblogic/index.html", "anchor": ""}, {"cmd": "shutdown('&lt;server_name&gt;', 'Server')", "tip": "Graceful shutdown of a managed server via WLST — lets in-flight requests finish, unlike killing the process outright.", "section": "WebLogic", "topic": "WebLogic", "page": "weblogic/index.html", "anchor": ""}, {"cmd": "$DOMAIN_HOME/bin/stopWebLogic.sh", "tip": "Stop the admin server via the vendor script — the supported way, avoids an unclean process kill.", "section": "WebLogic", "topic": "WebLogic", "page": "weblogic/index.html", "anchor": ""}, {"cmd": "$DOMAIN_HOME/bin/startNodeManager.sh", "tip": "Start Node Manager first — nmStart() calls in WLST need it running to actually work.", "section": "WebLogic", "topic": "WebLogic", "page": "weblogic/index.html", "anchor": ""}, {"cmd": "tail -f $DOMAIN_HOME/servers/AdminServer/logs/AdminServer.log", "tip": "Tail the admin server's own log — separate from managed server logs, admin-specific issues show up here only.", "section": "WebLogic", "topic": "WebLogic", "page": "weblogic/index.html", "anchor": ""}, {"cmd": "ls $DOMAIN_HOME/servers/", "tip": "List every managed server defined in this domain — confirms what actually exists before troubleshooting one by name.", "section": "WebLogic", "topic": "WebLogic", "page": "weblogic/index.html", "anchor": ""}, {"cmd": "kill -3 &lt;pid&gt;", "tip": "Trigger a thread dump to stdout/stderr log without restarting the JVM — first move on a hang, not a restart.", "section": "WebLogic", "topic": "WebLogic", "page": "weblogic/index.html", "anchor": ""}, {"cmd": "jstack &lt;pid&gt; &gt; threaddump_$(date +%s).txt", "tip": "Cleaner thread dump straight to a file — easier to diff between two hangs than scrolling console output.", "section": "WebLogic", "topic": "WebLogic", "page": "weblogic/index.html", "anchor": ""}, {"cmd": "keytool -list -v -keystore trust.jks", "tip": "Inspect a truststore's certs and expiry dates — the recurring fix for SSLHandshakeException.", "section": "WebLogic", "topic": "WebLogic", "page": "weblogic/index.html", "anchor": ""}, {"cmd": "keytool -importcert -alias &lt;alias&gt; -file &lt;cert.pem&gt; -keystore trust.jks", "tip": "Add a renewed CA cert to an existing truststore — the actual fix once you've confirmed an expired cert is the problem.", "section": "WebLogic", "topic": "WebLogic", "page": "weblogic/index.html", "anchor": ""}, {"cmd": "print cmo.getMessagesCurrentCount()", "tip": "Messages sitting in the queue right now — a growing count with no consumers means something downstream stopped processing.", "section": "WebLogic", "topic": "WebLogic", "page": "weblogic/index.html", "anchor": ""}, {"cmd": "print cmo.getConsumersCurrentCount()", "tip": "Active consumers — zero consumers with a growing count means nobody's draining it.", "section": "WebLogic", "topic": "WebLogic", "page": "weblogic/index.html", "anchor": ""}, {"cmd": "tail -f $DOMAIN_HOME/servers/&lt;server_name&gt;/logs/&lt;server_name&gt;.log", "tip": "Tail a managed server's own log directly — the fastest way to watch what one specific server is doing right now.", "section": "WebLogic", "topic": "WebLogic", "page": "weblogic/index.html", "anchor": ""}, {"cmd": "grep -i &quot;SEVERE\\|&lt;Error&gt;&quot; $DOMAIN_HOME/servers/&lt;server_name&gt;/logs/&lt;server_name&gt;.log | tail -50", "tip": "Last 50 severe/error lines — fast triage without opening the whole log file.", "section": "WebLogic", "topic": "WebLogic", "page": "weblogic/index.html", "anchor": ""}, {"cmd": "curl -s &quot;http://&lt;host&gt;:&lt;jolokia_port&gt;/jolokia/read/com.bea:Type=ServerRuntime,Name=&lt;server_name&gt;/State&quot;", "tip": "Read server state over Jolokia JMX-HTTP, no WLST session needed — useful from monitoring scripts.", "section": "WebLogic", "topic": "WebLogic", "page": "weblogic/index.html", "anchor": ""}, {"cmd": "netstat -an | grep &lt;port&gt;", "tip": "Confirm the port is listening at the OS level — independent of the app layer.", "section": "WebLogic", "topic": "WebLogic", "page": "weblogic/index.html", "anchor": ""}, {"cmd": "openssl s_client -connect &lt;host&gt;:&lt;port&gt; -showcerts", "tip": "Inspect the cert a WebLogic SSL listener presents — from outside the JVM.", "section": "WebLogic", "topic": "WebLogic", "page": "weblogic/index.html", "anchor": ""}, {"cmd": "keytool -list -v -keystore identity.jks | grep -A1 &quot;Valid from&quot;", "tip": "Check an identity keystore's own cert expiry — a different problem from a truststore issue, don't assume it's the same fix.", "section": "WebLogic", "topic": "WebLogic", "page": "weblogic/index.html", "anchor": ""}, {"cmd": "tail -100 $DOMAIN_HOME/servers/&lt;server_name&gt;/logs/&lt;server_name&gt;.log", "tip": "The actual startup error is almost always in the last lines — start reading from the bottom, not the top.", "section": "Troubleshooting", "topic": "WebLogic", "page": "weblogic/index.html", "anchor": "troubleshooting"}, {"cmd": "ps -ef | grep &lt;server_name&gt;", "tip": "Confirm it isn't already running under a stale process before retrying — a duplicate start attempt fails in a confusing way.", "section": "Troubleshooting", "topic": "WebLogic", "page": "weblogic/index.html", "anchor": "troubleshooting"}, {"cmd": "kill -3 &lt;pid&gt;", "tip": "Thread dump first, always — a restart destroys the evidence of what caused the hang.", "section": "Troubleshooting", "topic": "WebLogic", "page": "weblogic/index.html", "anchor": "troubleshooting"}, {"cmd": "grep -c &quot;BLOCKED&quot; threaddump.txt", "tip": "A high BLOCKED count usually means lock contention — not the same fix as raw overload, don't just add capacity.", "section": "Troubleshooting", "topic": "WebLogic", "page": "weblogic/index.html", "anchor": "troubleshooting"}, {"cmd": "grep -i &quot;OutOfMemoryError&quot; $DOMAIN_HOME/servers/&lt;server_name&gt;/logs/&lt;server_name&gt;.log", "tip": "Confirm it's heap, not PermGen/Metaspace — the message names which one.", "section": "Troubleshooting", "topic": "WebLogic", "page": "weblogic/index.html", "anchor": "troubleshooting"}, {"cmd": "jmap -heap &lt;pid&gt;", "tip": "Current heap usage breakdown — only works while the process is still alive, capture it before restarting.", "section": "Troubleshooting", "topic": "WebLogic", "page": "weblogic/index.html", "anchor": "troubleshooting"}, {"cmd": "promtool check config prometheus.yml", "tip": "Validate config before reloading — catches typos before they break scraping.", "section": "Prometheus", "topic": "Prometheus", "page": "prometheus/index.html", "anchor": ""}, {"cmd": "promtool check rules alerts.yml", "tip": "Validate alerting rules syntax — catches a broken rule before it's reloaded and silently fails.", "section": "Prometheus", "topic": "Prometheus", "page": "prometheus/index.html", "anchor": ""}, {"cmd": "curl -X POST http://&lt;host&gt;:9090/-/reload", "tip": "Hot-reload config without restarting the process — picks up scrape/rule changes with zero downtime.", "section": "Prometheus", "topic": "Prometheus", "page": "prometheus/index.html", "anchor": ""}, {"cmd": "curl http://&lt;host&gt;:9090/api/v1/targets | jq '.data.activeTargets[] | select(.health!=&quot;up&quot;)'", "tip": "Which targets are currently down — confirms scraping is actually working before trusting any metric from it.", "section": "Prometheus", "topic": "Prometheus", "page": "prometheus/index.html", "anchor": ""}, {"cmd": "curl -g 'http://&lt;host&gt;:9090/api/v1/query?query=up'", "tip": "Run a PromQL query straight from the CLI — no UI needed for a quick check or scripting.", "section": "Prometheus", "topic": "Prometheus", "page": "prometheus/index.html", "anchor": ""}, {"cmd": "curl -g 'http://&lt;host&gt;:9090/api/v1/query_range?query=up&amp;start=&lt;start&gt;&amp;end=&lt;end&gt;&amp;step=60s'", "tip": "Same query, but over a time range — needed for graphing, not just checking the current value.", "section": "Prometheus", "topic": "Prometheus", "page": "prometheus/index.html", "anchor": ""}, {"cmd": "curl http://&lt;host&gt;:9090/api/v1/rules", "tip": "Every alerting/recording rule currently loaded, with state — confirms a rule actually made it in after a reload.", "section": "Prometheus", "topic": "Prometheus", "page": "prometheus/index.html", "anchor": ""}, {"cmd": "curl http://&lt;host&gt;:9090/api/v1/labels", "tip": "Every label name Prometheus knows about — useful for discovering what you can actually filter/group by.", "section": "Prometheus", "topic": "Prometheus", "page": "prometheus/index.html", "anchor": ""}, {"cmd": "curl -g 'http://&lt;host&gt;:9090/api/v1/label/job/values'", "tip": "Every distinct value for one label — e.g. every job name being scraped.", "section": "Prometheus", "topic": "Prometheus", "page": "prometheus/index.html", "anchor": ""}, {"cmd": "avg_over_time(node_load1[5m])", "tip": "Average of a gauge metric over a window — smooths out noise a single instant value would show.", "section": "Prometheus", "topic": "Prometheus", "page": "prometheus/index.html", "anchor": ""}, {"cmd": "max by (instance) (node_memory_MemAvailable_bytes)", "tip": "Per-instance max — isolates the worst host instead of an average that hides it.", "section": "Prometheus", "topic": "Prometheus", "page": "prometheus/index.html", "anchor": ""}, {"cmd": "count(up == 1)", "tip": "How many targets are currently up, as a single number — a fast health count for a dashboard or alert.", "section": "Prometheus", "topic": "Prometheus", "page": "prometheus/index.html", "anchor": ""}, {"cmd": "topk(5, rate(http_requests_total[5m]))", "tip": "The 5 highest values right now — fastest way to find the noisiest series.", "section": "Prometheus", "topic": "Prometheus", "page": "prometheus/index.html", "anchor": ""}, {"cmd": "rate(http_requests_total[5m])", "tip": "Per-second request rate over a 5-minute window — the standard way to turn a counter into a usable rate.", "section": "Prometheus", "topic": "Prometheus", "page": "prometheus/index.html", "anchor": ""}, {"cmd": "increase(http_requests_total[1h])", "tip": "Total increase over the window — good for counting events, not rates.", "section": "Prometheus", "topic": "Prometheus", "page": "prometheus/index.html", "anchor": ""}, {"cmd": "histogram_quantile(0.95, rate(http_request_duration_seconds_bucket[5m]))", "tip": "P95 latency from a histogram metric — shows the experience of slower requests, not just the average.", "section": "Prometheus", "topic": "Prometheus", "page": "prometheus/index.html", "anchor": ""}, {"cmd": "up == 0", "tip": "Every target Prometheus currently can't scrape — the up==0 query is the fastest way to spot a scraping failure.", "section": "Prometheus", "topic": "Prometheus", "page": "prometheus/index.html", "anchor": ""}, {"cmd": "sum by (job) (rate(errors_total[5m]))", "tip": "Error rate grouped by job — the standard &quot;what's on fire&quot; query.", "section": "Prometheus", "topic": "Prometheus", "page": "prometheus/index.html", "anchor": ""}, {"cmd": "curl -s http://&lt;host&gt;:9090/api/v1/status/tsdb | jq", "tip": "TSDB stats — series count, chunk count, memory — useful when Prometheus itself is slow.", "section": "Prometheus", "topic": "Prometheus", "page": "prometheus/index.html", "anchor": ""}, {"cmd": "curl -s http://&lt;host&gt;:9093/api/v2/silences", "tip": "List active Alertmanager silences — confirms nobody muted the exact alert you're chasing.", "section": "Prometheus", "topic": "Prometheus", "page": "prometheus/index.html", "anchor": ""}, {"cmd": "amtool alert query --alertmanager.url=http://&lt;host&gt;:9093", "tip": "Query current firing alerts from the CLI — no UI needed to check what's actually firing right now.", "section": "Prometheus", "topic": "Prometheus", "page": "prometheus/index.html", "anchor": ""}, {"cmd": "amtool silence add alertname=&lt;alert_name&gt; --alertmanager.url=http://&lt;host&gt;:9093 --duration=2h --comment=&quot;planned maintenance&quot;", "tip": "Create a silence from the CLI — scriptable for maintenance windows.", "section": "Prometheus", "topic": "Prometheus", "page": "prometheus/index.html", "anchor": ""}, {"cmd": "promtool query instant http://&lt;host&gt;:9090 'up'", "tip": "Run a query via promtool instead of raw curl+jq — cleaner output, no manual JSON parsing.", "section": "Prometheus", "topic": "Prometheus", "page": "prometheus/index.html", "anchor": ""}, {"cmd": "curl http://&lt;host&gt;:9090/api/v1/targets | jq '.data.activeTargets[] | select(.health!=&quot;up&quot;) | {job: .labels.job, error: .lastError}'", "tip": "The actual scrape error, per target — the real reason a target is down, not just that it is.", "section": "Troubleshooting", "topic": "Prometheus", "page": "prometheus/index.html", "anchor": "troubleshooting"}, {"cmd": "curl http://&lt;target_host&gt;:&lt;target_port&gt;/metrics", "tip": "Confirm the target's endpoint is reachable — independent of Prometheus.", "section": "Troubleshooting", "topic": "Prometheus", "page": "prometheus/index.html", "anchor": "troubleshooting"}, {"cmd": "curl -s http://&lt;host&gt;:9090/api/v1/status/tsdb | jq '.data.seriesCountByMetricName[:10]'", "tip": "Top metrics by series count — cardinality explosions are the usual cause.", "section": "Troubleshooting", "topic": "Prometheus", "page": "prometheus/index.html", "anchor": "troubleshooting"}, {"cmd": "curl -H &quot;Authorization: Bearer &lt;api_key&gt;&quot; http://&lt;host&gt;:3000/api/dashboards/uid/&lt;uid&gt;", "tip": "Export a dashboard's JSON via API — the actual definition, useful for version control or migration.", "section": "Grafana", "topic": "Grafana", "page": "grafana/index.html", "anchor": ""}, {"cmd": "curl -H &quot;Authorization: Bearer &lt;api_key&gt;&quot; -X POST http://&lt;host&gt;:3000/api/dashboards/db \\\n  -H &quot;Content-Type: application/json&quot; -d @dashboard.json", "tip": "Import/update a dashboard from JSON — the reverse of exporting, for restoring or deploying a dashboard.", "section": "Grafana", "topic": "Grafana", "page": "grafana/index.html", "anchor": ""}, {"cmd": "curl -H &quot;Authorization: Bearer &lt;api_key&gt;&quot; http://&lt;host&gt;:3000/api/datasources", "tip": "List configured data sources — confirms what Grafana can actually query before building a panel.", "section": "Grafana", "topic": "Grafana", "page": "grafana/index.html", "anchor": ""}, {"cmd": "curl -H &quot;Authorization: Bearer &lt;api_key&gt;&quot; http://&lt;host&gt;:3000/api/alertmanager/grafana/api/v2/alerts", "tip": "Current alert state via API — scriptable check instead of opening the alerting UI.", "section": "Grafana", "topic": "Grafana", "page": "grafana/index.html", "anchor": ""}, {"cmd": "curl -H &quot;Authorization: Bearer &lt;api_key&gt;&quot; http://&lt;host&gt;:3000/api/dashboards/uid/&lt;uid&gt;/versions", "tip": "Every saved version of a dashboard, with who changed it — useful for finding when/why a panel broke.", "section": "Grafana", "topic": "Grafana", "page": "grafana/index.html", "anchor": ""}, {"cmd": "curl -H &quot;Authorization: Bearer &lt;api_key&gt;&quot; http://&lt;host&gt;:3000/api/org/users", "tip": "Every user in the current organization and their role — a permissions inventory without clicking through the UI.", "section": "Grafana", "topic": "Grafana", "page": "grafana/index.html", "anchor": ""}, {"cmd": "curl -H &quot;Authorization: Bearer &lt;api_key&gt;&quot; http://&lt;host&gt;:3000/api/folders", "tip": "Every dashboard folder — useful before scripting a bulk import into the right place.", "section": "Grafana", "topic": "Grafana", "page": "grafana/index.html", "anchor": ""}, {"cmd": "curl -H &quot;Authorization: Bearer &lt;api_key&gt;&quot; -X POST http://&lt;host&gt;:3000/api/annotations -d '{&quot;text&quot;:&quot;deploy v2.3&quot;,&quot;tags&quot;:[&quot;deploy&quot;]}' -H &quot;Content-Type: application/json&quot;", "tip": "Push an annotation marker onto graphs — e.g. from a CI/CD pipeline, so a deploy shows up directly on the graph.", "section": "Grafana", "topic": "Grafana", "page": "grafana/index.html", "anchor": ""}, {"cmd": "curl -H &quot;Authorization: Bearer &lt;api_key&gt;&quot; http://&lt;host&gt;:3000/api/health", "tip": "Quick liveness check — separate from whether dashboards actually render correctly.", "section": "Grafana", "topic": "Grafana", "page": "grafana/index.html", "anchor": ""}, {"cmd": "curl -H &quot;Authorization: Bearer &lt;api_key&gt;&quot; http://&lt;host&gt;:3000/api/search?query=&lt;dashboard_name&gt;", "tip": "Find a dashboard's UID by name — most other API calls need the UID, not the display name.", "section": "Grafana", "topic": "Grafana", "page": "grafana/index.html", "anchor": ""}, {"cmd": "curl -H &quot;Authorization: Bearer &lt;api_key&gt;&quot; http://&lt;host&gt;:3000/api/datasources/proxy/&lt;datasource_id&gt;/api/v1/query?query=up", "tip": "Query the data source through Grafana's own proxy — isolates whether the problem is Grafana's connection or the panel's query.", "section": "Troubleshooting", "topic": "Grafana", "page": "grafana/index.html", "anchor": "troubleshooting"}, {"cmd": "curl -H &quot;Authorization: Bearer &lt;api_key&gt;&quot; -X POST http://&lt;host&gt;:3000/api/datasources/&lt;id&gt;/health", "tip": "Grafana's own connectivity test — no dashboard needed.", "section": "Troubleshooting", "topic": "Grafana", "page": "grafana/index.html", "anchor": "troubleshooting"}, {"cmd": "cmk -R", "tip": "Reload monitoring core config after changes — like a targeted daemon-reload.", "section": "Check_MK", "topic": "Check_MK", "page": "checkmk/index.html", "anchor": ""}, {"cmd": "cmk -II &lt;hostname&gt;", "tip": "Rediscover services on a host from scratch (drops manual overrides on that host — see -I below for the safer version)", "section": "Check_MK", "topic": "Check_MK", "page": "checkmk/index.html", "anchor": ""}, {"cmd": "cmk -I &lt;hostname&gt;", "tip": "Discover new services only — leaves existing ones and any manual overrides untouched.", "section": "Check_MK", "topic": "Check_MK", "page": "checkmk/index.html", "anchor": ""}, {"cmd": "cmk -d &lt;hostname&gt;", "tip": "Show raw agent output for a host — the first thing to check when a check looks wrong.", "section": "Check_MK", "topic": "Check_MK", "page": "checkmk/index.html", "anchor": ""}, {"cmd": "check_mk_agent | less", "tip": "Run the agent locally on the host — see raw output before Check_MK processes it.", "section": "Check_MK", "topic": "Check_MK", "page": "checkmk/index.html", "anchor": ""}, {"cmd": "omd status", "tip": "Status of every service in an OMD site — Check_MK's own site manager, confirms the monitoring stack itself is healthy.", "section": "Check_MK", "topic": "Check_MK", "page": "checkmk/index.html", "anchor": ""}, {"cmd": "omd restart &lt;site_name&gt;", "tip": "Restart a specific monitoring site — scoped to one site, doesn't affect others running on the same host.", "section": "Check_MK", "topic": "Check_MK", "page": "checkmk/index.html", "anchor": ""}, {"cmd": "omd status &lt;site_name&gt;", "tip": "Status for just one site — useful when several sites run on the same host.", "section": "Check_MK", "topic": "Check_MK", "page": "checkmk/index.html", "anchor": ""}, {"cmd": "cmk-passwd &lt;username&gt;", "tip": "Set/reset a Check_MK web UI user's password from the CLI — for when you can't get in through the UI to do it.", "section": "Check_MK", "topic": "Check_MK", "page": "checkmk/index.html", "anchor": ""}, {"cmd": "cmk --list-hosts", "tip": "Every host currently configured in this site — a full inventory before troubleshooting one by name.", "section": "Check_MK", "topic": "Check_MK", "page": "checkmk/index.html", "anchor": ""}, {"cmd": "cmk --version", "tip": "Confirm the Check_MK version — matters since plugin compatibility varies by version.", "section": "Check_MK", "topic": "Check_MK", "page": "checkmk/index.html", "anchor": ""}, {"cmd": "cmk --debug -v &lt;hostname&gt;", "tip": "Verbose + full tracebacks on a check that's failing silently otherwise — surfaces the actual error instead of just a blank result.", "section": "Check_MK", "topic": "Check_MK", "page": "checkmk/index.html", "anchor": ""}, {"cmd": "cmk --scan-parents", "tip": "Auto-detect network parent/child relationships — produces cleaner topology maps without manual configuration.", "section": "Check_MK", "topic": "Check_MK", "page": "checkmk/index.html", "anchor": ""}, {"cmd": "tail -f ~/var/log/web.log", "tip": "Check_MK web UI log, inside the OMD site's home — useful when WATO changes don't seem to take effect.", "section": "Check_MK", "topic": "Check_MK", "page": "checkmk/index.html", "anchor": ""}, {"cmd": "cmk -O", "tip": "Activate pending changes from the CLI — same as the WATO button.", "section": "Check_MK", "topic": "Check_MK", "page": "checkmk/index.html", "anchor": ""}, {"cmd": "cmk --backup &lt;target_dir&gt;", "tip": "Back up the whole site's configuration and data — everything needed to restore this site elsewhere.", "section": "Check_MK", "topic": "Check_MK", "page": "checkmk/index.html", "anchor": ""}, {"cmd": "cmk --checks=&lt;check_name&gt; -v &lt;hostname&gt;", "tip": "Run one specific check — skips the full discovery cycle.", "section": "Check_MK", "topic": "Check_MK", "page": "checkmk/index.html", "anchor": ""}, {"cmd": "cmk -d &lt;hostname&gt;", "tip": "If this returns nothing, Check_MK can't reach the agent — check network/firewall between the monitoring server and the host first.", "section": "Troubleshooting", "topic": "Check_MK", "page": "checkmk/index.html", "anchor": "troubleshooting"}, {"cmd": "cmk -I &lt;hostname&gt;", "tip": "If the agent responds but no services show, run discovery — a host with zero discovered services was probably never added properly.", "section": "Troubleshooting", "topic": "Check_MK", "page": "checkmk/index.html", "anchor": "troubleshooting"}, {"cmd": "cmk -d &lt;hostname&gt; | grep -c &quot;^&lt;&lt;&lt;&quot;", "tip": "Count agent output sections — duplicates here mean two versions of the same plugin are both executable on the monitored host.", "section": "Troubleshooting", "topic": "Check_MK", "page": "checkmk/index.html", "anchor": "troubleshooting"}, {"cmd": "ls -la /usr/lib/check_mk_agent/plugins/", "tip": "Find the duplicate plugin — the fix is removing it, not debugging the check.", "section": "Troubleshooting", "topic": "Check_MK", "page": "checkmk/index.html", "anchor": "troubleshooting"}, {"cmd": "python3 -m venv .venv &amp;&amp; source .venv/bin/activate", "tip": "Isolated environment — always do this before pip install, avoids polluting the system Python.", "section": "Python", "topic": "Python", "page": "python/index.html", "anchor": ""}, {"cmd": "pip install -r requirements.txt", "tip": "Install a project's dependencies — the standard step after cloning a repo, before anything else runs.", "section": "Python", "topic": "Python", "page": "python/index.html", "anchor": ""}, {"cmd": "pip freeze &gt; requirements.txt", "tip": "Snapshot exactly what's installed — pin these versions so someone else's install matches yours.", "section": "Python", "topic": "Python", "page": "python/index.html", "anchor": ""}, {"cmd": "pip list --outdated", "tip": "What's got newer versions available — confirms what's actually outdated instead of guessing.", "section": "Python", "topic": "Python", "page": "python/index.html", "anchor": ""}, {"cmd": "python3 -m http.server 8000", "tip": "Instant file server, zero setup — great for pulling a file off a box with no other transfer option.", "section": "Python", "topic": "Python", "page": "python/index.html", "anchor": ""}, {"cmd": "python3 -m json.tool file.json", "tip": "Pretty-print / validate JSON from the CLI — no separate tool needed, Python already has this built in.", "section": "Python", "topic": "Python", "page": "python/index.html", "anchor": ""}, {"cmd": "python3 -c &quot;import socket; print(socket.gethostbyname('host'))&quot;", "tip": "Quick one-liner DNS check — confirms resolution works without leaving Python or installing dig.", "section": "Python", "topic": "Python", "page": "python/index.html", "anchor": ""}, {"cmd": "python3 -m pdb script.py", "tip": "Drop into the debugger on script start — steps through from the very first line instead of adding breakpoints manually.", "section": "Python", "topic": "Python", "page": "python/index.html", "anchor": ""}, {"cmd": "python3 -m timeit &quot;sorted([3,1,2])&quot;", "tip": "Microbenchmark a snippet — isolates timing for one specific piece of code, not a whole script.", "section": "Python", "topic": "Python", "page": "python/index.html", "anchor": ""}, {"cmd": "python3 -X importtime script.py 2&gt; importtime.log", "tip": "Profile what's actually slow at startup — surprisingly often a heavy import, not your own code.", "section": "Python", "topic": "Python", "page": "python/index.html", "anchor": ""}, {"cmd": "python3 -c &quot;import cProfile,pstats,sys; cProfile.run('exec(open(sys.argv[1]).read())', 'out.prof')&quot; script.py &amp;&amp; python3 -m pstats out.prof", "tip": "Profile a whole script's runtime, then explore hot functions interactively — snakeviz turns the raw profile into a readable visual.", "section": "Python", "topic": "Python", "page": "python/index.html", "anchor": ""}, {"cmd": "which python3 &amp;&amp; which pip", "tip": "Confirm both point into the SAME environment — installing into one venv and running another is the #1 cause.", "section": "Troubleshooting", "topic": "Python", "page": "python/index.html", "anchor": "troubleshooting"}, {"cmd": "pip show &lt;package_name&gt;", "tip": "Confirms whether it's actually installed in the currently active environment — not just installed somewhere on the system.", "section": "Troubleshooting", "topic": "Python", "page": "python/index.html", "anchor": "troubleshooting"}, {"cmd": "python3 --version", "tip": "Version mismatches between environments are common and easy to overlook — this catches one before it causes a confusing bug.", "section": "Troubleshooting", "topic": "Python", "page": "python/index.html", "anchor": "troubleshooting"}, {"cmd": "pip freeze &gt; actual-versions.txt", "tip": "Compare against requirements.txt — an unpinned dependency can silently upgrade and break behavior.", "section": "Troubleshooting", "topic": "Python", "page": "python/index.html", "anchor": "troubleshooting"}, {"cmd": "Get-Location", "tip": "Prints the current working directory — pwd equivalent.", "section": "Basic", "topic": "PowerShell", "page": "powershell/index.html", "anchor": "basic"}, {"cmd": "Set-Location C:\\path", "tip": "Changes the current working directory — cd equivalent.", "section": "Basic", "topic": "PowerShell", "page": "powershell/index.html", "anchor": "basic"}, {"cmd": "Copy-Item file.txt backup.txt", "tip": "Duplicates a file under a new name in the same folder — cp equivalent.", "section": "Basic", "topic": "PowerShell", "page": "powershell/index.html", "anchor": "basic"}, {"cmd": "Move-Item file.txt archive\\", "tip": "Moves (or renames, if the destination is a filename) a file — mv equivalent.", "section": "Basic", "topic": "PowerShell", "page": "powershell/index.html", "anchor": "basic"}, {"cmd": "Remove-Item file.txt", "tip": "Deletes a file — rm equivalent; add -Recurse for a folder and its contents.", "section": "Basic", "topic": "PowerShell", "page": "powershell/index.html", "anchor": "basic"}, {"cmd": "New-Item -ItemType Directory -Path newfolder", "tip": "Creates a new directory — mkdir equivalent.", "section": "Basic", "topic": "PowerShell", "page": "powershell/index.html", "anchor": "basic"}, {"cmd": "$var = &quot;value&quot;", "tip": "Assigns a variable for the current session — no export needed like in bash, it's just how assignment works here.", "section": "Basic", "topic": "PowerShell", "page": "powershell/index.html", "anchor": "basic"}, {"cmd": "$env:PATH", "tip": "Reads the PATH environment variable — the $env: prefix is how you access any env var.", "section": "Basic", "topic": "PowerShell", "page": "powershell/index.html", "anchor": "basic"}, {"cmd": "Get-Process | Sort-Object CPU -Descending | Select-Object -First 10", "tip": "Lists the 10 processes using the most CPU right now, heaviest first — the PowerShell equivalent of top -o %CPU.", "section": "Basic", "topic": "PowerShell", "page": "powershell/index.html", "anchor": "basic"}, {"cmd": "Get-Service | Where-Object {$_.Status -eq 'Running'}", "tip": "Filter, like grep but on real objects — matches on actual properties, not text patterns.", "section": "Basic", "topic": "PowerShell", "page": "powershell/index.html", "anchor": "basic"}, {"cmd": "Get-ChildItem -Recurse -File | Where-Object {$_.Length -gt 100MB}", "tip": "Recursively searches the current folder for any file over 100MB — spot what's actually eating disk space.", "section": "Basic", "topic": "PowerShell", "page": "powershell/index.html", "anchor": "basic"}, {"cmd": "Get-Content log.txt -Wait -Tail 20", "tip": "Streams a file's new lines as they're written — the PowerShell equivalent of tail -f, starts from the last 20 lines.", "section": "Basic", "topic": "PowerShell", "page": "powershell/index.html", "anchor": "basic"}, {"cmd": "Get-Command *service*", "tip": "Discover cmdlets by keyword — no need to memorize exact cmdlet names ahead of time.", "section": "Basic", "topic": "PowerShell", "page": "powershell/index.html", "anchor": "basic"}, {"cmd": "Get-Help Get-Process -Full", "tip": "Full docs for any cmdlet, offline — no need to search online mid-task.", "section": "Basic", "topic": "PowerShell", "page": "powershell/index.html", "anchor": "basic"}, {"cmd": "$_ | Get-Member", "tip": "Inspect what properties/methods an object actually has — the PowerShell equivalent of &quot;what fields does this JSON have&quot;.", "section": "Basic", "topic": "PowerShell", "page": "powershell/index.html", "anchor": "basic"}, {"cmd": "Invoke-Command -ComputerName host1,host2 -ScriptBlock { Get-Service }", "tip": "Run something on multiple remote machines at once — one command instead of looping manually.", "section": "Basic", "topic": "PowerShell", "page": "powershell/index.html", "anchor": "basic"}, {"cmd": "Test-NetConnection host -Port 443", "tip": "Checks whether a specific TCP port on a host is reachable — the PowerShell equivalent of nc -zv.", "section": "Basic", "topic": "PowerShell", "page": "powershell/index.html", "anchor": "basic"}, {"cmd": "ConvertTo-Json / ConvertFrom-Json", "tip": "Native JSON handling, no external tool — built into the shell, unlike bash which usually needs jq.", "section": "Basic", "topic": "PowerShell", "page": "powershell/index.html", "anchor": "basic"}, {"cmd": "Select-Object -ExpandProperty Name", "tip": "Unwrap a single property instead of the whole object — get just the value you need, not the full object dump.", "section": "Basic", "topic": "PowerShell", "page": "powershell/index.html", "anchor": "basic"}, {"cmd": "Get-ExecutionPolicy", "tip": "See the current restriction level — confirms why a script won't run before changing anything.", "section": "Troubleshooting", "topic": "PowerShell", "page": "powershell/index.html", "anchor": "troubleshooting"}, {"cmd": "Set-ExecutionPolicy RemoteSigned -Scope CurrentUser", "tip": "Allow locally-written scripts to run — scoped to your user, without loosening policy for the whole machine.", "section": "Troubleshooting", "topic": "PowerShell", "page": "powershell/index.html", "anchor": "troubleshooting"}, {"cmd": "Get-Module -ListAvailable &lt;module_name&gt;", "tip": "Confirm it's actually installed, and where — before assuming an import failure means it's missing entirely.", "section": "Troubleshooting", "topic": "PowerShell", "page": "powershell/index.html", "anchor": "troubleshooting"}, {"cmd": "Install-Module &lt;module_name&gt; -Scope CurrentUser", "tip": "Install for your user only — no admin rights needed, unlike a machine-wide install.", "section": "Troubleshooting", "topic": "PowerShell", "page": "powershell/index.html", "anchor": "troubleshooting"}, {"cmd": "git init", "tip": "Start a new repo in the current directory — creates the .git folder, nothing else changes.", "section": "Git", "topic": "Git", "page": "git/index.html", "anchor": ""}, {"cmd": "git clone &lt;url&gt;", "tip": "Copy an existing remote repo locally — includes full history, not just the current files.", "section": "Git", "topic": "Git", "page": "git/index.html", "anchor": ""}, {"cmd": "git status", "tip": "What's changed, staged, and untracked right now — the first command to run before doing anything else.", "section": "Git", "topic": "Git", "page": "git/index.html", "anchor": ""}, {"cmd": "git add &lt;file&gt;", "tip": "Stage a file's changes for the next commit — staging is separate from committing, lets you build a commit piece by piece.", "section": "Git", "topic": "Git", "page": "git/index.html", "anchor": ""}, {"cmd": "git add .", "tip": "Stage everything changed in the current directory — fast, but review with status first so you don't stage something unintended.", "section": "Git", "topic": "Git", "page": "git/index.html", "anchor": ""}, {"cmd": "git commit -m &quot;message&quot;", "tip": "Commit staged changes with a message — only what was staged goes in, not everything changed.", "section": "Git", "topic": "Git", "page": "git/index.html", "anchor": ""}, {"cmd": "git commit -am &quot;message&quot;", "tip": "Stage tracked changes and commit in one step — skips new/untracked files.", "section": "Git", "topic": "Git", "page": "git/index.html", "anchor": ""}, {"cmd": "git push", "tip": "Send local commits to the remote — makes your work visible/available to others.", "section": "Git", "topic": "Git", "page": "git/index.html", "anchor": ""}, {"cmd": "git pull", "tip": "Fetch + merge the remote's changes into your current branch — the combined step most people mean by &quot;pull&quot;.", "section": "Git", "topic": "Git", "page": "git/index.html", "anchor": ""}, {"cmd": "git fetch", "tip": "Download remote changes without merging them yet — lets you inspect what changed before integrating it.", "section": "Git", "topic": "Git", "page": "git/index.html", "anchor": ""}, {"cmd": "git branch", "tip": "List local branches — the current one is marked with an asterisk.", "section": "Git", "topic": "Git", "page": "git/index.html", "anchor": ""}, {"cmd": "git branch &lt;name&gt;", "tip": "Create a new branch without switching to it — useful when setting up branches ahead of time.", "section": "Git", "topic": "Git", "page": "git/index.html", "anchor": ""}, {"cmd": "git checkout &lt;branch&gt;", "tip": "Switch to an existing branch — your working directory updates to match it.", "section": "Git", "topic": "Git", "page": "git/index.html", "anchor": ""}, {"cmd": "git checkout -b &lt;branch&gt;", "tip": "Create a branch and switch to it in one step — the common case when starting new work.", "section": "Git", "topic": "Git", "page": "git/index.html", "anchor": ""}, {"cmd": "git switch &lt;branch&gt;", "tip": "The newer, clearer alternative to checkout — checkout historically did too many unrelated things.", "section": "Git", "topic": "Git", "page": "git/index.html", "anchor": ""}, {"cmd": "git merge &lt;branch&gt;", "tip": "Merge another branch into the current one — brings its commits in, may create a merge commit.", "section": "Git", "topic": "Git", "page": "git/index.html", "anchor": ""}, {"cmd": "git log", "tip": "Commit history, full form — shows author, date, and full message for each commit.", "section": "Git", "topic": "Git", "page": "git/index.html", "anchor": ""}, {"cmd": "git log --oneline", "tip": "Commit history, one line per commit — much easier to scan than the full form.", "section": "Git", "topic": "Git", "page": "git/index.html", "anchor": ""}, {"cmd": "git diff", "tip": "Unstaged changes vs the last commit — what you'd be committing if you staged everything right now.", "section": "Git", "topic": "Git", "page": "git/index.html", "anchor": ""}, {"cmd": "git diff --staged", "tip": "Staged changes vs the last commit — exactly what the next commit would actually contain.", "section": "Git", "topic": "Git", "page": "git/index.html", "anchor": ""}, {"cmd": "git remote -v", "tip": "Every remote configured, with their URLs — confirms you're pushing/pulling from where you think.", "section": "Git", "topic": "Git", "page": "git/index.html", "anchor": ""}, {"cmd": "git tag &lt;name&gt;", "tip": "Tag the current commit, e.g. for a release — tags mark a specific point in history by name.", "section": "Git", "topic": "Git", "page": "git/index.html", "anchor": ""}, {"cmd": "git log --oneline --graph --all --decorate", "tip": "The single most useful &quot;what's actually going on&quot; view — shows branches, merges, and history together.", "section": "Git", "topic": "Git", "page": "git/index.html", "anchor": ""}, {"cmd": "git reflog", "tip": "Recover commits after a bad reset — your safety net.", "section": "Git", "topic": "Git", "page": "git/index.html", "anchor": ""}, {"cmd": "git bisect start / good / bad", "tip": "Binary search for the commit that introduced a bug — far faster than checking commits one by one.", "section": "Git", "topic": "Git", "page": "git/index.html", "anchor": ""}, {"cmd": "git stash -p", "tip": "Interactively stash only some hunks — useful when only part of your changes should be set aside.", "section": "Git", "topic": "Git", "page": "git/index.html", "anchor": ""}, {"cmd": "git rebase -i HEAD~5", "tip": "Squash/reorder/edit the last 5 commits — cleans up history before sharing it.", "section": "Git", "topic": "Git", "page": "git/index.html", "anchor": ""}, {"cmd": "git blame -L 40,60 file.py", "tip": "Who changed just these lines, not the whole file — narrows blame output to what actually matters.", "section": "Git", "topic": "Git", "page": "git/index.html", "anchor": ""}, {"cmd": "git cherry-pick &lt;sha&gt;", "tip": "Apply one specific commit onto the current branch — grabs just that fix without merging the whole branch.", "section": "Git", "topic": "Git", "page": "git/index.html", "anchor": ""}, {"cmd": "git worktree add ../hotfix hotfix-branch", "tip": "Work on two branches in two directories — no stashing/switching needed to jump between them.", "section": "Git", "topic": "Git", "page": "git/index.html", "anchor": ""}, {"cmd": "git diff --stat", "tip": "Summary of what changed, file by file — the line-count overview without the actual diff noise.", "section": "Git", "topic": "Git", "page": "git/index.html", "anchor": ""}, {"cmd": "git log -S&quot;functionName&quot; --oneline", "tip": "Find every commit that added or removed a specific string/function — much sharper than blame when you're hunting for when something was introduced.", "section": "Git", "topic": "Git", "page": "git/index.html", "anchor": ""}, {"cmd": "git rebase -i --autosquash HEAD~10", "tip": "Auto-orders fixup!/squash! commits into place — pair with `git commit --fixup &lt;sha&gt;` while working, then one clean rebase at the end.", "section": "Git", "topic": "Git", "page": "git/index.html", "anchor": ""}, {"cmd": "git status", "tip": "Lists every conflicted file — the starting point for resolving a merge conflict.", "section": "Troubleshooting", "topic": "Git", "page": "git/index.html", "anchor": "troubleshooting"}, {"cmd": "git diff --name-only --diff-filter=U", "tip": "Same info as status, but easier to pipe into a script — just the filenames, no extra formatting.", "section": "Troubleshooting", "topic": "Git", "page": "git/index.html", "anchor": "troubleshooting"}, {"cmd": "git checkout --ours &lt;file&gt;", "tip": "Take your version entirely for one file — only right when the whole file should just be yours, not a real merge.", "section": "Troubleshooting", "topic": "Git", "page": "git/index.html", "anchor": "troubleshooting"}, {"cmd": "git checkout --theirs &lt;file&gt;", "tip": "Or take theirs entirely — for anything more nuanced, edit the conflict markers by hand.", "section": "Troubleshooting", "topic": "Git", "page": "git/index.html", "anchor": "troubleshooting"}, {"cmd": "git reset --soft HEAD~1", "tip": "Undo the last commit — only safe if not pushed yet.", "section": "Troubleshooting", "topic": "Git", "page": "git/index.html", "anchor": "troubleshooting"}, {"cmd": "git checkout -b temp-branch", "tip": "Save your current work under a real branch name — detached HEAD commits become unreachable once you switch away.", "section": "Troubleshooting", "topic": "Git", "page": "git/index.html", "anchor": "troubleshooting"}, {"cmd": "git branch --contains &lt;sha&gt;", "tip": "Confirm which branches contain a commit — check before deleting anything.", "section": "Troubleshooting", "topic": "Git", "page": "git/index.html", "anchor": "troubleshooting"}, {"cmd": "jq '.items[] | select(.status==&quot;Running&quot;) | .name' pods.json", "tip": "Filter + extract in one line — combines a condition and field selection without a separate pass.", "section": "YAML / JSON / JQ", "topic": "YAML / JSON / JQ", "page": "data-formats/index.html", "anchor": ""}, {"cmd": "jq -r '.[] | [.name,.status] | @csv' data.json", "tip": "Converts a JSON array into CSV rows — pick the fields you want, in order.", "section": "YAML / JSON / JQ", "topic": "YAML / JSON / JQ", "page": "data-formats/index.html", "anchor": ""}, {"cmd": "yq '.spec.replicas' deployment.yaml", "tip": "Reads one value out of a YAML file by path — the jq equivalent for YAML.", "section": "YAML / JSON / JQ", "topic": "YAML / JSON / JQ", "page": "data-formats/index.html", "anchor": ""}, {"cmd": "yq -i '.spec.replicas = 3' deployment.yaml", "tip": "Updates one value inside a YAML file directly — safer and more scriptable than hand-editing the file.", "section": "YAML / JSON / JQ", "topic": "YAML / JSON / JQ", "page": "data-formats/index.html", "anchor": ""}, {"cmd": "python3 -c &quot;import yaml,sys; yaml.safe_load(open(sys.argv[1]))&quot; file.yaml", "tip": "Validate YAML syntax with zero extra tools — Python already ships a YAML parser you can call directly.", "section": "YAML / JSON / JQ", "topic": "YAML / JSON / JQ", "page": "data-formats/index.html", "anchor": ""}, {"cmd": "jq -n --argjson a &quot;$(cat a.json)&quot; --argjson b &quot;$(cat b.json)&quot; '$a * $b'", "tip": "Deep-merge two JSON objects — $b's keys win on conflict, nested objects merge recursively instead of one replacing the other.", "section": "YAML / JSON / JQ", "topic": "YAML / JSON / JQ", "page": "data-formats/index.html", "anchor": ""}, {"cmd": "yq -o=json '.' config.yaml | jq '.'", "tip": "Convert YAML to JSON in one pipeline — then use jq's full feature set.", "section": "YAML / JSON / JQ", "topic": "YAML / JSON / JQ", "page": "data-formats/index.html", "anchor": ""}, {"cmd": "jq -e . file.json &gt; /dev/null", "tip": "E forces a non-zero exit on invalid JSON, without printing anything on success — good for scripting a validity check.", "section": "Troubleshooting", "topic": "YAML / JSON / JQ", "page": "data-formats/index.html", "anchor": "troubleshooting"}, {"cmd": "cat -A file.json | head -3", "tip": "Look for invisible characters — a BOM or CRLF that breaks parsing but hides in a normal editor.", "section": "Troubleshooting", "topic": "YAML / JSON / JQ", "page": "data-formats/index.html", "anchor": "troubleshooting"}, {"cmd": "yq --version", "tip": "Confirm which yq — the Go version (mikefarah) and the Python wrapper (kislyuk) have different flag syntax and are easy to mix up.", "section": "Troubleshooting", "topic": "YAML / JSON / JQ", "page": "data-formats/index.html", "anchor": "troubleshooting"}, {"cmd": "yq -i '.spec.template.spec.containers[0].image = &quot;myimage:v2&quot;' deployment.yaml", "tip": "Array index needed explicitly — a bare .containers.image silently matches nothing if it's actually a list.", "section": "Troubleshooting", "topic": "YAML / JSON / JQ", "page": "data-formats/index.html", "anchor": "troubleshooting"}, {"cmd": "systemctl status svc", "tip": "Is it even trying to run — and what's the last error before it stopped.", "section": "how to think about any problem", "topic": "Troubleshooting", "page": "troubleshooting/index.html", "anchor": "general-approach-how-to-think-about-any-problem"}, {"cmd": "journalctl -u svc -n 100 --no-pager", "tip": "Recent logs, no pager to fight with — --no-pager dumps straight to the terminal instead of an interactive view.", "section": "how to think about any problem", "topic": "Troubleshooting", "page": "troubleshooting/index.html", "anchor": "general-approach-how-to-think-about-any-problem"}, {"cmd": "ss -tulnp | grep &lt;port&gt;", "tip": "Is anything actually listening — confirms the service bound to the port at all, before checking anything else.", "section": "how to think about any problem", "topic": "Troubleshooting", "page": "troubleshooting/index.html", "anchor": "general-approach-how-to-think-about-any-problem"}, {"cmd": "top -o %CPU", "tip": "Sorted live view, heaviest CPU consumer at the top — the fastest way to spot the actual culprit.", "section": "how to think about any problem", "topic": "Troubleshooting", "page": "troubleshooting/index.html", "anchor": "general-approach-how-to-think-about-any-problem"}, {"cmd": "strace -p &lt;pid&gt; -c", "tip": "Is it doing real work or spinning on syscalls — distinguishes genuine CPU load from a process stuck in a loop.", "section": "how to think about any problem", "topic": "Troubleshooting", "page": "troubleshooting/index.html", "anchor": "general-approach-how-to-think-about-any-problem"}, {"cmd": "df -h", "tip": "Usage per mounted filesystem — confirms which one is actually full, not just that disk usage is high somewhere.", "section": "how to think about any problem", "topic": "Troubleshooting", "page": "troubleshooting/index.html", "anchor": "general-approach-how-to-think-about-any-problem"}, {"cmd": "du -sh --max-depth=1 /suspect | sort -rh", "tip": "Biggest subdirectories first, one level deep — no guessing where space went.", "section": "how to think about any problem", "topic": "Troubleshooting", "page": "troubleshooting/index.html", "anchor": "general-approach-how-to-think-about-any-problem"}, {"cmd": "lsof +D /path", "tip": "Check for deleted-but-still-open files — df/du disagreeing is the classic sign.", "section": "how to think about any problem", "topic": "Troubleshooting", "page": "troubleshooting/index.html", "anchor": "general-approach-how-to-think-about-any-problem"}, {"cmd": "ip route get &lt;ip&gt;", "tip": "Which route/interface would be used — confirms traffic is even going out the path you expect.", "section": "how to think about any problem", "topic": "Troubleshooting", "page": "troubleshooting/index.html", "anchor": "general-approach-how-to-think-about-any-problem"}, {"cmd": "mtr &lt;host&gt;", "tip": "Where exactly it breaks — mtr shows which specific hop is dropping packets, not just that connectivity failed.", "section": "how to think about any problem", "topic": "Troubleshooting", "page": "troubleshooting/index.html", "anchor": "general-approach-how-to-think-about-any-problem"}, {"cmd": "ss -s", "tip": "Socket summary — check for exhaustion (TIME_WAIT pileup etc.)", "section": "how to think about any problem", "topic": "Troubleshooting", "page": "troubleshooting/index.html", "anchor": "general-approach-how-to-think-about-any-problem"}, {"cmd": "keytool -list -v -keystore trust.jks | grep -A1 'Valid from'", "tip": "For Java truststores specifically — a different tool than openssl, since it's reading a Java keystore format.", "section": "how to think about any problem", "topic": "Troubleshooting", "page": "troubleshooting/index.html", "anchor": "general-approach-how-to-think-about-any-problem"}, {"cmd": "curl -o /dev/null -s -w '%{time_total}s\\n' https://endpoint", "tip": "Confirm it's actually slow, not just perceived — a real number beats a feeling before you start debugging.", "section": "how to think about any problem", "topic": "Troubleshooting", "page": "troubleshooting/index.html", "anchor": "general-approach-how-to-think-about-any-problem"}, {"cmd": "vmstat 1 5", "tip": "CPU-bound vs I/O-bound at a glance — points you toward the right next command instead of guessing.", "section": "how to think about any problem", "topic": "Troubleshooting", "page": "troubleshooting/index.html", "anchor": "general-approach-how-to-think-about-any-problem"}, {"cmd": "iostat -xz 1", "tip": "Disk %util — a common hidden cause.", "section": "how to think about any problem", "topic": "Troubleshooting", "page": "troubleshooting/index.html", "anchor": "general-approach-how-to-think-about-any-problem"}, {"cmd": "kubectl top pods --sort-by=cpu", "tip": "Check if it's a specific pod hogging resources — narrows a cluster-wide slowdown to one culprit.", "section": "how to think about any problem", "topic": "Troubleshooting", "page": "troubleshooting/index.html", "anchor": "general-approach-how-to-think-about-any-problem"}, {"cmd": "kubectl rollout history deployment/myapp", "tip": "Confirm what actually changed and when — a rollout history beats trusting memory of what was deployed.", "section": "how to think about any problem", "topic": "Troubleshooting", "page": "troubleshooting/index.html", "anchor": "general-approach-how-to-think-about-any-problem"}, {"cmd": "kubectl rollout undo deployment/myapp", "tip": "Roll back first, investigate after — restore service before root-causing.", "section": "how to think about any problem", "topic": "Troubleshooting", "page": "troubleshooting/index.html", "anchor": "general-approach-how-to-think-about-any-problem"}, {"cmd": "git log --oneline -10", "tip": "What changed in the code between the working and broken version — the actual diff, not a guess at what might have broken it.", "section": "how to think about any problem", "topic": "Troubleshooting", "page": "troubleshooting/index.html", "anchor": "general-approach-how-to-think-about-any-problem"}, {"cmd": "kubectl diff -f manifest.yaml", "tip": "If it's a config/manifest change, see exactly what's different — confirms the real diff instead of assuming what changed.", "section": "how to think about any problem", "topic": "Troubleshooting", "page": "troubleshooting/index.html", "anchor": "general-approach-how-to-think-about-any-problem"}];
